-- Complete candidate canonical packets for the corrected ankling, low-pogo,
-- straight-leg march/bound, ladder, and bound-to-sprint family.
--
-- Five definitions have exact enough movement contracts to become structurally
-- selectable after independent approval. Four underspecified labels retain
-- active cards only so their evidence and identity questions stay visible;
-- their variants and profiles are non-prescribable.
--
-- Exercise cards store exercise complexity and physical difficulty only;
-- overall difficulty is their maximum. Athlete proficiency belongs only to
-- coaching.skill. Evidence, media, graph, calibration, cards, and scores remain
-- candidate/review-only. This migration creates no approval.

DO $$
DECLARE
  migration_key CONSTANT TEXT :=
    '413_coaching_ankling_straight_leg_research_completion';
  research_batch CONSTANT TEXT := 'ankling-straight-leg-drills-v1';
  active_slugs CONSTANT TEXT[] := ARRAY[
    'ankle-pogo-in-place','ankling-pogo-hop','ankling-drill',
    'fast-ankling-pogo-march','distance-jump-straight-leg-bound-march',
    'distance-jump-straight-leg-bound','straight-leg-ankling-ladder',
    'straight-leg-bounds-to-sprint','wall-ankling-pogo'
  ];
  selectable_slugs CONSTANT TEXT[] := ARRAY[
    'ankle-pogo-in-place','ankling-drill',
    'distance-jump-straight-leg-bound-march',
    'distance-jump-straight-leg-bound','straight-leg-bounds-to-sprint'
  ];
  audited_source_ids CONSTANT BIGINT[] :=
    ARRAY[48,96,97,323,338,947,974,981,1085,1109,1112,1119,1138,1638];
  already_applied_count INTEGER;
  actual_count INTEGER;
  protected_count INTEGER;
BEGIN
  SELECT count(*) INTO actual_count
  FROM coaching.exercise_definition_v1 definition
  WHERE definition.facility_id=1 AND definition.slug=ANY(active_slugs)
    AND definition.status<>'archived';
  IF actual_count<>9 THEN
    RAISE EXCEPTION '% requires exactly nine active corrected definitions; found %',
      migration_key,actual_count;
  END IF;

  SELECT count(*) INTO already_applied_count
  FROM coaching.exercise_definition_v1 definition
  WHERE definition.facility_id=1 AND definition.slug=ANY(active_slugs)
    AND definition.status<>'archived'
    AND definition.provenance_json->>'researchCompletionMigration'=migration_key;
  IF already_applied_count NOT IN(0,9) THEN
    RAISE EXCEPTION '% found partial prior application on % definitions',
      migration_key,already_applied_count;
  END IF;
  IF already_applied_count=0 AND EXISTS(
    SELECT 1 FROM coaching.exercise_definition_v1 definition
    WHERE definition.facility_id=1 AND definition.slug=ANY(active_slugs)
      AND definition.status<>'archived' AND definition.card_version<>1
  ) THEN
    RAISE EXCEPTION '% expected card version 1 before first application',migration_key;
  END IF;
  IF already_applied_count = 9 AND EXISTS(
    SELECT 1 FROM coaching.exercise_definition_v1 definition
    WHERE definition.facility_id=1 AND definition.slug=ANY(active_slugs)
      AND definition.status<>'archived' AND definition.card_version <> 2
  ) THEN
    RAISE EXCEPTION '% found card-version drift after completion',migration_key;
  END IF;

  SELECT count(*) INTO actual_count
  FROM coaching.exercise_definition_v1 definition
  JOIN coaching.exercise_definition_source_v1 source
    ON source.definition_id=definition.id
  WHERE definition.facility_id=1 AND definition.slug=ANY(active_slugs)
    AND definition.status<>'archived'
    AND source.legacy_exercise_id=ANY(audited_source_ids);
  IF actual_count<>cardinality(audited_source_ids) OR EXISTS(
    SELECT 1 FROM coaching.exercise_definition_v1 definition
    JOIN coaching.exercise_definition_source_v1 source
      ON source.definition_id=definition.id
    WHERE definition.facility_id=1 AND definition.slug=ANY(active_slugs)
      AND definition.status<>'archived'
      AND NOT(source.legacy_exercise_id=ANY(audited_source_ids))
  ) THEN
    RAISE EXCEPTION '% requires exactly all % audited source mappings',
      migration_key,cardinality(audited_source_ids);
  END IF;

  SELECT count(*) INTO actual_count
  FROM coaching.exercise_definition_v1 definition
  JOIN coaching.exercise_variant_v1 variant ON variant.definition_id=definition.id
  WHERE definition.facility_id=1 AND definition.slug=ANY(active_slugs)
    AND definition.status<>'archived' AND variant.status<>'archived';
  IF actual_count<>9 OR EXISTS(
    SELECT 1 FROM coaching.exercise_definition_v1 definition
    JOIN coaching.exercise_variant_v1 variant ON variant.definition_id=definition.id
    WHERE definition.facility_id=1 AND definition.slug=ANY(active_slugs)
      AND definition.status<>'archived' AND variant.status<>'archived'
      AND variant.variant_key<>'baseline'
  ) THEN
    RAISE EXCEPTION '% requires one active baseline variant per definition',migration_key;
  END IF;

  SELECT
    (SELECT count(*) FROM coaching.exercise_definition_v1 definition
      WHERE definition.facility_id=1 AND definition.slug=ANY(active_slugs)
        AND definition.status<>'archived'
        AND (definition.status='published' OR definition.reviewed_by IS NOT NULL
          OR definition.approved_by IS NOT NULL
          OR definition.last_reviewed_at IS NOT NULL
          OR definition.approved_video_url IS NOT NULL))
    +(SELECT count(*) FROM coaching.exercise_section_evidence_v1 evidence
      JOIN coaching.exercise_definition_v1 definition
        ON definition.id=evidence.definition_id
      WHERE definition.slug=ANY(active_slugs)
        AND evidence.review_status NOT IN('candidate','superseded'))
    +(SELECT count(*) FROM coaching.exercise_media_candidate_v1 media
      JOIN coaching.exercise_definition_v1 definition
        ON definition.id=media.definition_id
      WHERE definition.slug=ANY(active_slugs)
        AND media.review_status NOT IN('candidate','superseded'))
    +(SELECT count(*) FROM coaching.exercise_alternate_assessment_v1 alternate
      JOIN coaching.exercise_definition_v1 definition
        ON definition.id=alternate.definition_id
      WHERE definition.slug=ANY(active_slugs)
        AND alternate.review_status NOT IN('candidate','superseded'))
    +(SELECT count(*) FROM coaching.exercise_card_review_v1 review
      JOIN coaching.exercise_definition_v1 definition
        ON definition.id=review.definition_id
      WHERE definition.slug=ANY(active_slugs))
    +(SELECT count(*) FROM coaching.exercise_card_revision_v1 revision
      JOIN coaching.exercise_definition_v1 definition
        ON definition.id=revision.definition_id
      WHERE definition.slug=ANY(active_slugs))
    +(SELECT count(*) FROM coaching.exercise_media_review_v1 review
      JOIN coaching.exercise_definition_v1 definition
        ON definition.id=review.definition_id
      WHERE definition.slug=ANY(active_slugs))
    +(SELECT count(*) FROM coaching.exercise_variant_v1 variant
      JOIN coaching.exercise_definition_v1 definition
        ON definition.id=variant.definition_id
      WHERE definition.slug=ANY(active_slugs) AND variant.status='published')
    +(SELECT count(*) FROM coaching.exercise_delivery_profile_v1 profile
      JOIN coaching.exercise_variant_v1 variant ON variant.id=profile.variant_id
      JOIN coaching.exercise_definition_v1 definition
        ON definition.id=variant.definition_id
      WHERE definition.slug=ANY(active_slugs) AND profile.status='published')
    +(SELECT count(*) FROM coaching.exercise_relationship_v1 relationship
      JOIN coaching.exercise_variant_v1 from_variant
        ON from_variant.id=relationship.from_variant_id
      JOIN coaching.exercise_variant_v1 to_variant
        ON to_variant.id=relationship.to_variant_id
      WHERE (from_variant.definition_id IN(
          SELECT id FROM coaching.exercise_definition_v1 WHERE slug=ANY(active_slugs))
        OR to_variant.definition_id IN(
          SELECT id FROM coaching.exercise_definition_v1 WHERE slug=ANY(active_slugs)))
        AND (relationship.review_status<>'review'
          OR relationship.reviewed_by IS NOT NULL
          OR relationship.reviewed_at IS NOT NULL))
    +(SELECT count(*) FROM coaching.exercise_score_calibration_v1 calibration
      JOIN coaching.exercise_variant_v1 variant ON variant.id=calibration.variant_id
      JOIN coaching.exercise_definition_v1 definition
        ON definition.id=variant.definition_id
      WHERE definition.slug=ANY(active_slugs)
        AND (calibration.status<>'review' OR calibration.reviewed_by IS NOT NULL
          OR calibration.reviewed_at IS NOT NULL))
    +(SELECT count(*) FROM coaching.exercise_score_v1 score
      WHERE score.exercise_id=ANY(audited_source_ids)
        AND (score.human_review_status<>'queued' OR score.reviewed_by IS NOT NULL
          OR score.reviewed_at IS NOT NULL))
  INTO protected_count;
  IF protected_count>0 THEN
    RAISE EXCEPTION '% refused to overwrite % reviewed or published record(s)',
      migration_key,protected_count;
  END IF;

  CREATE TEMP TABLE family_packet_seed(
    definition_slug TEXT PRIMARY KEY,
    research_version TEXT NOT NULL,
    packet_json JSONB NOT NULL
  ) ON COMMIT DROP;
  INSERT INTO family_packet_seed VALUES
  -- BEGIN GENERATED CANONICAL RESEARCH PACKETS
    ('ankle-pogo-in-place','2026-07-25.7',$packet${"assessmentSummary":{"identity":"Stationary bilateral low-amplitude vertical hops produced predominantly through coordinated foot and ankle spring behavior, with small natural knee and hip motion and continuous quiet contacts.","currentCardFindings":["The description and summary contain broken generated grammar and overstate direct jump-height transfer.","Two baseline variants prescribe conflicting doses of 3 contacts versus 20 contacts, so the current repetition unit is unsafe and ambiguous.","The identity duplicates Low Pogos and probably Ankling Pogo Hop; anatomy, load, fatigue, surface, and population constraints need explicit treatment."],"proposedTaxonomy":{"movementPatterns":["stationary_bilateral_low_pogo","vertical_repeated_stretch_shortening_cycle"],"jointActions":["metatarsophalangeal_extension","ankle_dorsiflexion","ankle_plantarflexion","small_knee_and_hip_flexion_extension"],"planes":["sagittal"],"laterality":"bilateral_synchronous","intent":"repeatable_low_amplitude_contacts_without_squat_strategy"},"proposedAnatomy":{"primaryMuscles":["soleus","gastrocnemius","intrinsic_foot"],"secondaryMuscles":["tibialis_anterior","quadriceps","gluteus_maximus","lumbopelvic_stabilizers"],"joints":["foot","ankle","knee","hip","lumbopelvic_complex"]},"proposedDifficulty":{"technicalComplexity":28,"absoluteLoadDemand":22,"coordinationDemand":32,"supervisionDemand":24,"failureConsequence":30,"impact":31,"workCapacityDemand":25,"baseOverallDifficulty":28},"proposedLoadProfile":{"loadingType":"bodyweight_bilateral_repeated_low_amplitude_plyometric","impactClass":"low_to_moderate_by_amplitude_surface_and_contact_count","landingContactsPerRep":"one_contact_per_hop; prescribe_total_contacts_or_seconds","primaryStress":["foot_intrinsic_load","plantar_flexor_force","achilles_tendon_cycling"],"fatigueSensitivity":"contact_sound_amplitude_knee_dominance_cadence_and_symptom_response"},"proposedConstraints":{"requiredEquipment":["clear_level_non_slip_surface"],"optionalEquipment":["contact_counter","metronome","video"],"environment":["forgiving_surface","adequate_ceiling","no_cross_traffic"],"population":["pain_free_bilateral_calf_raise","tolerates_low_hops","can_stop_on_command"]},"proposedDosage":{"sets":"1-4","contactsPerSet":"8-20_or_5-15_seconds","restSeconds":"30-90_by_intent","intensity":"low_amplitude_submaximal","progressWhen":"contacts stay quiet, vertical, symmetric, pain-free, and cadence does not decay"},"proposedInstructions":{"coachCues":["Stay tall","Small quiet bounces","Spring through the whole foot","Keep the knees soft, not locked"],"athleteInstructions":["Bounce in place at low height and stop while every contact still feels quick"],"commonFaults":["turning_into_squat_jumps","forced_tiptoe_position","heel_slamming","locked_knees","fatigue_chasing"]},"proposedSafety":{"readiness":["pain_free_calf_raise","controlled_bilateral_landing","safe_surface"],"stopRules":["pain","asymmetry","loud_contacts","amplitude_or_cadence_drop","excessive_knee_bend","loss_of_balance"]},"programmingDecision":"Retain as the stable stationary bilateral low-pogo identity, consolidate Low Pogos as an alias or phase-specific delivery profile, resolve the duplicate baseline dose, and quarantine Ankling Pogo Hop until its contact pattern is confirmed.","currentCardSnapshot":{"capturedAt":"2026-07-26T02:10:00.000Z","cardVersion":1,"status":"review","description":"The athlete performs Ankle Pogo in Place as a quality-first jump-height drill, emphasizing builds low-amplitude springiness and teaches the athlete to return force without sinking into long ground contacts.","familyKey":"Elastic ankle stiffness","movementPatterns":[],"bodyRegions":[],"requiredEquipment":[],"optionalEquipment":[],"environment":{},"population":{},"difficulty":{"absoluteLoadDemand":20,"coordinationDemand":40,"technicalComplexity":40,"baseOverallDifficulty":40},"loadProfile":{},"fatigueProfile":{}}},"evidence":[{"sectionKey":"identity","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["World Athletics describes ankling as a progressive running drill that begins with learning a toe-to-ground loading action and then increases cadence.","Ankle Pogo in Place must state whether it is stationary or traveling, bilateral or alternating, walking, marching, dribbling, hopping, or bounding, its knee strategy, contact sequence, displacement, cadence, and terminal transition; spring or stiffness alone does not define identity."]},{"sectionKey":"taxonomy","sourceUrl":"https://worldathletics.org/download/download?filename=152a49b1-8225-498e-8283-9c580dcd45d9.pdf&urlslug=Women%27s+100m+-+2017+IAAF+World+Championships+Biomechanical+report","sourceTitle":"Women's 100 m — 2017 IAAF World Championships Biomechanical Report","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":82,"claims":["World Athletics treats straight-leg shuffle into sprinting as a drill progression that can be combined into a movement pattern congruent with the technical model.","Ankle Pogo in Place belongs to either low-amplitude cyclic plyometrics, sprint-mechanics locomotion, straight-leg shuffle or bound mechanics, or a compound transition; those categories must not be merged into one undifferentiated exercise."]},{"sectionKey":"anatomy","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/37989833/","sourceTitle":"Ankle and Plantar Flexor Muscle-Tendon Unit Function in Sprinters: A Narrative Review","sourcePublisher":"Sports Medicine","sourceKind":"peer_reviewed_research","evidenceQuality":89,"claims":["The ankle and plantar-flexor muscle-tendon units make phase-specific contributions to sprinting, with distinct roles for soleus and gastrocnemius and important energy transfer at maximum velocity.","The card should identify intrinsic foot, plantar-flexor, tibialis-anterior, knee-extensor, hamstring, hip-flexor and extensor, lumbopelvic, and arm-action roles according to the actual drill rather than labeling every drill ankle-only."]},{"sectionKey":"biomechanics","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8008308/","sourceTitle":"Kinematic Stride Characteristics of Maximal Sprint Running of Elite Sprinters – Verification of the Swing-Pull Technique","sourcePublisher":"Journal of Human Kinetics","sourceKind":"peer_reviewed_research","evidenceQuality":84,"claims":["Active foot contact with backswing velocity, small horizontal foot distance from the center of mass at contact, hip-extension velocity, and controlled support-leg flexion may help minimize braking during maximal sprinting.","Ankle Pogo in Place should cue contact close to the projected center of mass and observable rhythm without claiming that an isolated drill automatically reproduces or improves full-speed sprint mechanics."]},{"sectionKey":"difficulty","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8553457/","sourceTitle":"Application of Leg, Vertical, and Joint Stiffness in Running Performance: A Literature Overview","sourcePublisher":"Journal of Healthcare Engineering","sourceKind":"peer_reviewed_research","evidenceQuality":86,"claims":["Mechanical stiffness is task- and velocity-dependent, changes with fatigue, and represents coordinated whole-limb behavior rather than a fixed athlete trait.","Exercise difficulty must directly score technical complexity, physical and absolute-load demand, coordination, supervision, failure consequence, impact, work-capacity demand, and overall difficulty; audience labels are not part of exercise difficulty."]},{"sectionKey":"load_fatigue_recovery","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8938535/","sourceTitle":"Effects of Plyometric Training on Lower Body Muscle Architecture, Tendon Structure, Stiffness and Physical Performance: A Systematic Review and Meta-analysis","sourcePublisher":"Sports Medicine - Open","sourceKind":"peer_reviewed_research","evidenceQuality":91,"claims":["Plyometric training can change tendon stiffness and performance, so low-amplitude contacts still require progressive exposure and contact-volume accounting.","Ankle Pogo in Place needs total and per-leg contacts, lane distance, surface, footwear, amplitude, cadence or velocity, approach and transition distance, technical-fatigue markers, between-attempt recovery, and weekly impact accounting."]},{"sectionKey":"constraints","sourceUrl":"https://www.nsca.com/contentassets/116c55d64e1343d2b264e05aaf158a91/basics_of_strength_and_conditioning_manual.pdf","sourceTitle":"Basics of Strength and Conditioning Manual","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":84,"claims":["Plyometric and sprint drills require progressive preparation, safe surfaces and lanes, suitable footwear, spacing, recovery, and supervision matched to intensity and complexity.","The card should require a level, dry, non-slip lane with a deceleration zone when traveling; a secured ladder only for the ladder variant; and an athlete who can tolerate the selected contact amplitude without pain or compensatory mechanics."]},{"sectionKey":"dosage","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["World Athletics gives an example of two passes over 10 to 20 metres for ankling and related running drills, while instructing athletes to learn the movement before increasing pace.","Use passes, metres, seconds, and explicit contacts rather than ambiguous repetitions; low-skill learning passes may use walk-back recovery, while bounds and bound-to-sprint transitions need fuller recovery and immediate quality stops."]},{"sectionKey":"instructions","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8008308/","sourceTitle":"Kinematic Stride Characteristics of Maximal Sprint Running of Elite Sprinters – Verification of the Swing-Pull Technique","sourcePublisher":"Journal of Human Kinetics","sourceKind":"peer_reviewed_research","evidenceQuality":84,"claims":["Sprint-contact instruction should prioritize observable contact placement, active downward and backward foot velocity, posture, and rhythm rather than an unsupported promise of ideal technique.","Use a small task-specific cue set: stay stacked, keep steps short for ankling, contact close to the hips, preserve dorsiflexion without forcing a forefoot strike, let the heel behave naturally, and transition without reaching or locking the knee."]},{"sectionKey":"safety_stop_rules","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/37989833/","sourceTitle":"Ankle and Plantar Flexor Muscle-Tendon Unit Function in Sprinters: A Narrative Review","sourcePublisher":"Sports Medicine","sourceKind":"peer_reviewed_research","evidenceQuality":89,"claims":["Sprint plantar-flexor demand changes across start, acceleration, and maximum-velocity phases and should not be represented as uniformly low load.","Stop for foot, shin, calf, Achilles, hamstring, knee, hip, or back pain; loss of balance; repeated reaching or hard heel strike; locked-knee braking; loud or lengthening contacts; cadence drop; asymmetry; ladder displacement; or an unsafe sprint transition."]},{"sectionKey":"programming","sourceUrl":"https://worldathletics.org/download/download?filename=152a49b1-8225-498e-8283-9c580dcd45d9.pdf&urlslug=Women%27s+100m+-+2017+IAAF+World+Championships+Biomechanical+report","sourceTitle":"Women's 100 m — 2017 IAAF World Championships Biomechanical Report","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":82,"claims":["Sprint drills can progress from simpler to more complex tasks and combine into a sprint transition when the movement time and pattern fit the intended technical model.","Ankle Pogo in Place belongs after temperature and tissue preparation and before high-speed sprinting or high-output jumping; use learning versions in a mechanics block and bound or sprint-transition versions in a fresh output block."]},{"sectionKey":"athlete_support","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["Athlete support should show the exact movement at learning and performance cadence, the lane, contact sound, heel behavior, arm action, finish, and how a successful pass differs from merely moving the feet quickly.","Explain that stiffness means controlled resistance to collapse, not locking the knees or forcing the ankle, and show a lower-amplitude or slower-cadence option that preserves the identity."]},{"sectionKey":"coach_support","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8553457/","sourceTitle":"Application of Leg, Vertical, and Joint Stiffness in Running Performance: A Literature Overview","sourcePublisher":"Journal of Healthcare Engineering","sourceKind":"peer_reviewed_research","evidenceQuality":86,"claims":["Stiffness measures vary by task, speed, fatigue, maturity, and method, so coaches should not infer tendon or joint stiffness from appearance alone.","Provide side and rear observation, contact and distance counts, cadence or timing only when reliably measured, left-right comparison, surface and lane setup, phase placement, regression and progression rules, and a distinction between technical cueing and verified biomechanical measurement."]},{"sectionKey":"accessibility","sourceUrl":"https://www.nsca.com/globalassets/about/position-statements/position_stand_youth_resistance_training---2009.pdf","sourceTitle":"Youth Resistance Training: Updated Position Statement Paper From the NSCA","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":88,"claims":["Exercise selection and progression should match readiness, technical competence, supervision, equipment scale, and the individual's physical and psychosocial context.","Accessibility options include shorter lanes, slower cadence, supported ankle loading, no-flight ankling, fewer contacts, visual floor marks instead of a raised ladder, quieter settings, extra demonstration, and longer recovery without converting audience context into an exercise-card classification."]},{"sectionKey":"alternates","sourceUrl":"https://worldathletics.org/download/download?filename=152a49b1-8225-498e-8283-9c580dcd45d9.pdf&urlslug=Women%27s+100m+-+2017+IAAF+World+Championships+Biomechanical+report","sourceTitle":"Women's 100 m — 2017 IAAF World Championships Biomechanical Report","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":82,"claims":["A straight-leg shuffle into sprint is a compound drill progression, not merely a renamed stationary ankle hop.","Cadence, pass length, contact cap, and coaching intent are delivery annotations; stationary versus traveling, bilateral versus alternating, flight versus no flight, straight-leg bound versus march, ladder constraint, and a terminal sprint may require a controlled variant or distinct definition."]},{"sectionKey":"media","sourceUrl":"https://support.google.com/youtube/answer/171780?expand=PrivacyEnhancedMode&hl=en","sourceTitle":"Embed videos and playlists","sourcePublisher":"YouTube Help","sourceKind":"manufacturer_instruction","evidenceQuality":82,"claims":["YouTube supports privacy-enhanced embedding through youtube-nocookie.com.","The direct candidates for Ankle Pogo in Place were discovered through visible YouTube search; current availability and embedding, exact movement identity and variant match, complete viewing, captions, instructional quality, safety, and approval remain separate review gates, and no candidate is approved by this packet."]}],"mediaCandidates":[{"url":"https://www.youtube.com/watch?v=wa1ClvLqSHo","title":"Ankle Pogo Jumps","channelName":"Hockey Training Exercise Demonstrations","sourceQuery":"low pogo jump ankle stiffness drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=j0nl5dWuqN4","title":"Pogo Jumps Tutorial - Proper Form and Technique","channelName":"Runna","sourceQuery":"low pogo jump ankle stiffness drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=W0nK_eBArXM","title":"Low Pogo Jumps","channelName":"Champion Physical Therapy and Performance","sourceQuery":"low pogo jump ankle stiffness drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=-BT77h5qPbU","title":"Pogo Jumps | Build Reactive Strength & Ankle Stiffness","channelName":"GRIT LAB","sourceQuery":"low pogo jump ankle stiffness drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=L_khHgMz9uU","title":"Pogo Jumps","channelName":"Unapproved visible-search candidate","sourceQuery":"low pogo jump ankle stiffness drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."}],"alternateAssessments":[{"name":"Low Pogos","classification":"same_identity","rationale":"The current card describes the same stationary bilateral low-amplitude ankle-dominant contacts.","distinguishingDimensions":{"phasePlacement":"prepare_or_output_by_intensity"}},{"name":"Ankling Pogo Hop","classification":"reject","rationale":"The current card does not state whether contacts are bilateral, alternating, stationary, or traveling; reject until human identity review resolves the movement.","distinguishingDimensions":{"contactSequence":"unresolved"}},{"name":"High Pogo","classification":"new_variant","rationale":"Higher amplitude materially increases impact and whole-limb contribution.","distinguishingDimensions":{"amplitude":"high"}},{"name":"Single-Leg Pogo in Place","classification":"new_definition","rationale":"Unilateral repeated contacts materially change laterality and tissue demand.","distinguishingDimensions":{"laterality":"unilateral"}},{"name":"Forward Low Pogo","classification":"new_variant","rationale":"Travel and horizontal braking change execution and lane requirements.","distinguishingDimensions":{"displacement":"forward"}}]}$packet$::JSONB),
    ('ankling-pogo-hop','2026-07-25.7',$packet${"assessmentSummary":{"identity":"Unresolved low-amplitude pogo or ankling drill whose stationary or traveling displacement, bilateral or alternating contact pattern, and hop sequence are not specified by the current card.","currentCardFindings":["The name combines ankling, pogo, and hop without defining which movement occurs.","The execution text is generic jump-template language and includes hip and knee actions inconsistent with the stated ankle-stiffness emphasis.","This card cannot safely enter generation until contact pattern, displacement, cadence, and laterality are adjudicated."],"proposedTaxonomy":{"movementPatterns":["unresolved_low_amplitude_contact_drill"],"jointActions":["unresolved"],"planes":["unresolved"],"laterality":"unresolved","intent":"unresolved_between_stationary_pogo_and_traveling_ankling"},"proposedAnatomy":{"primaryMuscles":["unresolved_pending_identity"],"secondaryMuscles":["unresolved_pending_identity"],"joints":["foot","ankle","knee","hip"]},"proposedDifficulty":{"technicalComplexity":40,"absoluteLoadDemand":24,"coordinationDemand":44,"supervisionDemand":45,"failureConsequence":36,"impact":34,"workCapacityDemand":25,"baseOverallDifficulty":40},"proposedLoadProfile":{"loadingType":"unresolved_bodyweight_repeated_contact","impactClass":"unresolved_low_to_moderate","landingContactsPerRep":"must_be_defined_before_use","primaryStress":["foot_and_ankle_cyclic_load"],"fatigueSensitivity":"cannot_be_calibrated_until_identity_is_resolved"},"proposedConstraints":{"requiredEquipment":["safe_surface","human_identity_review"],"optionalEquipment":["video"],"environment":["quarantined_from_generation"],"population":["none_until_identity_is_resolved"]},"proposedDosage":{"sets":"not_prescribable","contactsPerSet":"not_prescribable","restSeconds":"not_prescribable","intensity":"not_prescribable","progressWhen":"identity, laterality, displacement, and contact sequence are approved"},"proposedInstructions":{"coachCues":["Do not coach from the current card"],"athleteInstructions":["Await an exact movement demonstration"],"commonFaults":["mixing_distinct_drills","generic_jump_template","undefined_contact_pattern"]},"proposedSafety":{"readiness":["human_identity_adjudication"],"stopRules":["do_not_generate_or_prescribe"]},"programmingDecision":"Quarantine. Merge into Ankle Pogo in Place if stationary bilateral, into a traveling pogo variant if bilateral and moving, or into Ankling Drill if alternating no-flight locomotion.","currentCardSnapshot":{"capturedAt":"2026-07-26T02:10:00.000Z","cardVersion":1,"status":"review","description":"Ankling Pogo Hop is a neural-focused drill for ankle stiffness, foot reactivity, and short ground contact. It gives the athlete a short, crisp exposure that improves readiness, timing, perception, or output without becoming conditioning.","familyKey":"Plyometric stiffness","movementPatterns":[],"bodyRegions":[],"requiredEquipment":[],"optionalEquipment":[],"environment":{},"population":{},"difficulty":{"absoluteLoadDemand":10,"coordinationDemand":40,"technicalComplexity":40,"baseOverallDifficulty":40},"loadProfile":{},"fatigueProfile":{}}},"evidence":[{"sectionKey":"identity","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["World Athletics describes ankling as a progressive running drill that begins with learning a toe-to-ground loading action and then increases cadence.","Ankling Pogo Hop must state whether it is stationary or traveling, bilateral or alternating, walking, marching, dribbling, hopping, or bounding, its knee strategy, contact sequence, displacement, cadence, and terminal transition; spring or stiffness alone does not define identity."]},{"sectionKey":"taxonomy","sourceUrl":"https://worldathletics.org/download/download?filename=152a49b1-8225-498e-8283-9c580dcd45d9.pdf&urlslug=Women%27s+100m+-+2017+IAAF+World+Championships+Biomechanical+report","sourceTitle":"Women's 100 m — 2017 IAAF World Championships Biomechanical Report","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":82,"claims":["World Athletics treats straight-leg shuffle into sprinting as a drill progression that can be combined into a movement pattern congruent with the technical model.","Ankling Pogo Hop belongs to either low-amplitude cyclic plyometrics, sprint-mechanics locomotion, straight-leg shuffle or bound mechanics, or a compound transition; those categories must not be merged into one undifferentiated exercise."]},{"sectionKey":"anatomy","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/37989833/","sourceTitle":"Ankle and Plantar Flexor Muscle-Tendon Unit Function in Sprinters: A Narrative Review","sourcePublisher":"Sports Medicine","sourceKind":"peer_reviewed_research","evidenceQuality":89,"claims":["The ankle and plantar-flexor muscle-tendon units make phase-specific contributions to sprinting, with distinct roles for soleus and gastrocnemius and important energy transfer at maximum velocity.","The card should identify intrinsic foot, plantar-flexor, tibialis-anterior, knee-extensor, hamstring, hip-flexor and extensor, lumbopelvic, and arm-action roles according to the actual drill rather than labeling every drill ankle-only."]},{"sectionKey":"biomechanics","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8008308/","sourceTitle":"Kinematic Stride Characteristics of Maximal Sprint Running of Elite Sprinters – Verification of the Swing-Pull Technique","sourcePublisher":"Journal of Human Kinetics","sourceKind":"peer_reviewed_research","evidenceQuality":84,"claims":["Active foot contact with backswing velocity, small horizontal foot distance from the center of mass at contact, hip-extension velocity, and controlled support-leg flexion may help minimize braking during maximal sprinting.","Ankling Pogo Hop should cue contact close to the projected center of mass and observable rhythm without claiming that an isolated drill automatically reproduces or improves full-speed sprint mechanics."]},{"sectionKey":"difficulty","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8553457/","sourceTitle":"Application of Leg, Vertical, and Joint Stiffness in Running Performance: A Literature Overview","sourcePublisher":"Journal of Healthcare Engineering","sourceKind":"peer_reviewed_research","evidenceQuality":86,"claims":["Mechanical stiffness is task- and velocity-dependent, changes with fatigue, and represents coordinated whole-limb behavior rather than a fixed athlete trait.","Exercise difficulty must directly score technical complexity, physical and absolute-load demand, coordination, supervision, failure consequence, impact, work-capacity demand, and overall difficulty; audience labels are not part of exercise difficulty."]},{"sectionKey":"load_fatigue_recovery","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8938535/","sourceTitle":"Effects of Plyometric Training on Lower Body Muscle Architecture, Tendon Structure, Stiffness and Physical Performance: A Systematic Review and Meta-analysis","sourcePublisher":"Sports Medicine - Open","sourceKind":"peer_reviewed_research","evidenceQuality":91,"claims":["Plyometric training can change tendon stiffness and performance, so low-amplitude contacts still require progressive exposure and contact-volume accounting.","Ankling Pogo Hop needs total and per-leg contacts, lane distance, surface, footwear, amplitude, cadence or velocity, approach and transition distance, technical-fatigue markers, between-attempt recovery, and weekly impact accounting."]},{"sectionKey":"constraints","sourceUrl":"https://www.nsca.com/contentassets/116c55d64e1343d2b264e05aaf158a91/basics_of_strength_and_conditioning_manual.pdf","sourceTitle":"Basics of Strength and Conditioning Manual","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":84,"claims":["Plyometric and sprint drills require progressive preparation, safe surfaces and lanes, suitable footwear, spacing, recovery, and supervision matched to intensity and complexity.","The card should require a level, dry, non-slip lane with a deceleration zone when traveling; a secured ladder only for the ladder variant; and an athlete who can tolerate the selected contact amplitude without pain or compensatory mechanics."]},{"sectionKey":"dosage","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["World Athletics gives an example of two passes over 10 to 20 metres for ankling and related running drills, while instructing athletes to learn the movement before increasing pace.","Use passes, metres, seconds, and explicit contacts rather than ambiguous repetitions; low-skill learning passes may use walk-back recovery, while bounds and bound-to-sprint transitions need fuller recovery and immediate quality stops."]},{"sectionKey":"instructions","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8008308/","sourceTitle":"Kinematic Stride Characteristics of Maximal Sprint Running of Elite Sprinters – Verification of the Swing-Pull Technique","sourcePublisher":"Journal of Human Kinetics","sourceKind":"peer_reviewed_research","evidenceQuality":84,"claims":["Sprint-contact instruction should prioritize observable contact placement, active downward and backward foot velocity, posture, and rhythm rather than an unsupported promise of ideal technique.","Use a small task-specific cue set: stay stacked, keep steps short for ankling, contact close to the hips, preserve dorsiflexion without forcing a forefoot strike, let the heel behave naturally, and transition without reaching or locking the knee."]},{"sectionKey":"safety_stop_rules","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/37989833/","sourceTitle":"Ankle and Plantar Flexor Muscle-Tendon Unit Function in Sprinters: A Narrative Review","sourcePublisher":"Sports Medicine","sourceKind":"peer_reviewed_research","evidenceQuality":89,"claims":["Sprint plantar-flexor demand changes across start, acceleration, and maximum-velocity phases and should not be represented as uniformly low load.","Stop for foot, shin, calf, Achilles, hamstring, knee, hip, or back pain; loss of balance; repeated reaching or hard heel strike; locked-knee braking; loud or lengthening contacts; cadence drop; asymmetry; ladder displacement; or an unsafe sprint transition."]},{"sectionKey":"programming","sourceUrl":"https://worldathletics.org/download/download?filename=152a49b1-8225-498e-8283-9c580dcd45d9.pdf&urlslug=Women%27s+100m+-+2017+IAAF+World+Championships+Biomechanical+report","sourceTitle":"Women's 100 m — 2017 IAAF World Championships Biomechanical Report","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":82,"claims":["Sprint drills can progress from simpler to more complex tasks and combine into a sprint transition when the movement time and pattern fit the intended technical model.","Ankling Pogo Hop belongs after temperature and tissue preparation and before high-speed sprinting or high-output jumping; use learning versions in a mechanics block and bound or sprint-transition versions in a fresh output block."]},{"sectionKey":"athlete_support","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["Athlete support should show the exact movement at learning and performance cadence, the lane, contact sound, heel behavior, arm action, finish, and how a successful pass differs from merely moving the feet quickly.","Explain that stiffness means controlled resistance to collapse, not locking the knees or forcing the ankle, and show a lower-amplitude or slower-cadence option that preserves the identity."]},{"sectionKey":"coach_support","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8553457/","sourceTitle":"Application of Leg, Vertical, and Joint Stiffness in Running Performance: A Literature Overview","sourcePublisher":"Journal of Healthcare Engineering","sourceKind":"peer_reviewed_research","evidenceQuality":86,"claims":["Stiffness measures vary by task, speed, fatigue, maturity, and method, so coaches should not infer tendon or joint stiffness from appearance alone.","Provide side and rear observation, contact and distance counts, cadence or timing only when reliably measured, left-right comparison, surface and lane setup, phase placement, regression and progression rules, and a distinction between technical cueing and verified biomechanical measurement."]},{"sectionKey":"accessibility","sourceUrl":"https://www.nsca.com/globalassets/about/position-statements/position_stand_youth_resistance_training---2009.pdf","sourceTitle":"Youth Resistance Training: Updated Position Statement Paper From the NSCA","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":88,"claims":["Exercise selection and progression should match readiness, technical competence, supervision, equipment scale, and the individual's physical and psychosocial context.","Accessibility options include shorter lanes, slower cadence, supported ankle loading, no-flight ankling, fewer contacts, visual floor marks instead of a raised ladder, quieter settings, extra demonstration, and longer recovery without converting audience context into an exercise-card classification."]},{"sectionKey":"alternates","sourceUrl":"https://worldathletics.org/download/download?filename=152a49b1-8225-498e-8283-9c580dcd45d9.pdf&urlslug=Women%27s+100m+-+2017+IAAF+World+Championships+Biomechanical+report","sourceTitle":"Women's 100 m — 2017 IAAF World Championships Biomechanical Report","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":82,"claims":["A straight-leg shuffle into sprint is a compound drill progression, not merely a renamed stationary ankle hop.","Cadence, pass length, contact cap, and coaching intent are delivery annotations; stationary versus traveling, bilateral versus alternating, flight versus no flight, straight-leg bound versus march, ladder constraint, and a terminal sprint may require a controlled variant or distinct definition."]},{"sectionKey":"media","sourceUrl":"https://support.google.com/youtube/answer/171780?expand=PrivacyEnhancedMode&hl=en","sourceTitle":"Embed videos and playlists","sourcePublisher":"YouTube Help","sourceKind":"manufacturer_instruction","evidenceQuality":82,"claims":["YouTube supports privacy-enhanced embedding through youtube-nocookie.com.","The direct candidates for Ankling Pogo Hop were discovered through visible YouTube search; current availability and embedding, exact movement identity and variant match, complete viewing, captions, instructional quality, safety, and approval remain separate review gates, and no candidate is approved by this packet."]}],"mediaCandidates":[{"url":"https://www.youtube.com/watch?v=wa1ClvLqSHo","title":"Ankle Pogo Jumps","channelName":"Hockey Training Exercise Demonstrations","sourceQuery":"low pogo jump ankle stiffness drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=W0nK_eBArXM","title":"Low Pogo Jumps","channelName":"Champion Physical Therapy and Performance","sourceQuery":"low pogo jump ankle stiffness drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=yah2nVOHpuk","title":"Ankling (Running Drill)","channelName":"The Barefoot Sprinter","sourceQuery":"ankling sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=GgBk4sB5mwQ","title":"Sprint Drill: Ankling - Dribble","channelName":"Bodyfit Performance","sourceQuery":"ankling sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=es_7EB9ki8w","title":"Running Drills: Ankling","channelName":"Alp Fitness","sourceQuery":"ankling sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."}],"alternateAssessments":[{"name":"Ankle Pogo in Place","classification":"reject","rationale":"Do not merge until a human confirms that the intended drill is stationary and bilateral.","distinguishingDimensions":{"adjudication":"stationary_bilateral"}},{"name":"Ankling Drill","classification":"reject","rationale":"Do not merge until a human confirms that the intended drill is alternating traveling no-flight ankling.","distinguishingDimensions":{"adjudication":"traveling_alternating"}},{"name":"Forward Pogo","classification":"reject","rationale":"Do not author this variant until a human confirms bilateral hopping with forward displacement.","distinguishingDimensions":{"adjudication":"traveling_bilateral"}},{"name":"Single-Leg Pogo","classification":"new_definition","rationale":"A unilateral hop sequence requires a distinct identity.","distinguishingDimensions":{"laterality":"unilateral"}},{"name":"Fast Ankling Pogo March","classification":"reject","rationale":"That card uses similarly conflated terminology and is rejected until human identity review resolves it.","distinguishingDimensions":{"identity":"ambiguous_hybrid"}}]}$packet$::JSONB),
    ('ankling-drill','2026-07-25.7',$packet${"assessmentSummary":{"identity":"Traveling alternating ankling with very short cyclic contacts close to the hips, small knee motion, tall organized posture, and cadence selected to preserve contact quality.","currentCardFindings":["This is the best stable base definition for Ankling Walk and Ankling / Dribble March.","The current phrase 'forefoot contact' is too prescriptive; foot loading, heel behavior, and contact location should be coached without forcing a universal strike pattern.","The 15-second dose needs distance or contact caps and a stop rule tied to sound, reach, posture, and symptoms."],"proposedTaxonomy":{"movementPatterns":["traveling_alternating_ankling","low_amplitude_sprint_mechanics"],"jointActions":["ankle_dorsiflexion","ankle_plantarflexion","small_hip_and_knee_cycle"],"planes":["sagittal"],"laterality":"alternating_left_right","intent":"repeatable_short_contacts_and_cyclic_foot_loading"},"proposedAnatomy":{"primaryMuscles":["soleus","gastrocnemius","tibialis_anterior","intrinsic_foot"],"secondaryMuscles":["hamstrings","hip_flexors","gluteus_maximus","obliques","spinal_stabilizers"],"joints":["foot","ankle","knee","hip","lumbopelvic_complex","shoulder"]},"proposedDifficulty":{"technicalComplexity":42,"absoluteLoadDemand":19,"coordinationDemand":50,"supervisionDemand":34,"failureConsequence":27,"impact":23,"workCapacityDemand":24,"baseOverallDifficulty":42},"proposedLoadProfile":{"loadingType":"bodyweight_traveling_alternating_low_amplitude_locomotion","impactClass":"low","landingContactsPerRep":"record_pass_distance_and_optional_total_steps","primaryStress":["foot_loading_timing","plantar_flexor_cyclic_load","rapid_coordination"],"fatigueSensitivity":"step_length_contact_sound_posture_cadence_and_relaxation"},"proposedConstraints":{"requiredEquipment":["10_to_20_metre_clear_lane"],"optionalEquipment":["cones","video","cadence_feedback"],"environment":["level_non_slip_surface","safe_finish_zone"],"population":["pain_free_walking_and_calf_raise","can_keep_short_alternating_steps"]},"proposedDosage":{"sets":"2-4_passes","distancePerPass":"10-20_metres_or_8-15_seconds","restSeconds":"walk_back_or_30-60","intensity":"submaximal_learning_to_crisp_cadence","progressWhen":"contacts remain short, quiet, close to the hips, and technically repeatable"},"proposedInstructions":{"coachCues":["Tiny steps","Contact close to the hips","Stay tall and relaxed","Cadence without reaching"],"athleteInstructions":["Cycle your feet in very small steps and let speed come from rhythm, not stride length"],"commonFaults":["overstriding","high_knee_substitution","forced_forefoot_strike","heel_collapse","excessive_tension"]},"proposedSafety":{"readiness":["pain_free_gait","pain_free_calf_raise","safe_lane"],"stopRules":["pain","limp","repeated_reaching","loud_contacts","posture_loss","cadence_decay"]},"programmingDecision":"Retain as the stable traveling ankling identity. Migrate Ankling Walk and Ankling / Dribble March into cadence or delivery profiles unless a separately defined dribble cycle is approved.","currentCardSnapshot":{"capturedAt":"2026-07-26T02:10:00.000Z","cardVersion":1,"status":"review","description":"Ankling Drill is a sprint access & mechanics exercise for speed, sprinting, and quick-release athletes. It emphasizes ankle dorsiflexion, forefoot contact, elastic ankle rocker while keeping the session intent aligned with the Vortex phase sequence.","familyKey":"Foot-Ankle Rhythm","movementPatterns":[],"bodyRegions":[],"requiredEquipment":[],"optionalEquipment":[],"environment":{},"population":{},"difficulty":{"absoluteLoadDemand":10,"coordinationDemand":40,"technicalComplexity":40,"baseOverallDifficulty":40},"loadProfile":{},"fatigueProfile":{}}},"evidence":[{"sectionKey":"identity","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublishe