s","sourceKind":"governing_body","evidenceQuality":82,"claims":["Sprint drills can progress from simpler to more complex tasks and combine into a sprint transition when the movement time and pattern fit the intended technical model.","Straight-Leg Bound belongs after temperature and tissue preparation and before high-speed sprinting or high-output jumping; use learning versions in a mechanics block and bound or sprint-transition versions in a fresh output block."]},{"sectionKey":"athlete_support","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["Athlete support should show the exact movement at learning and performance cadence, the lane, contact sound, heel behavior, arm action, finish, and how a successful pass differs from merely moving the feet quickly.","Explain that stiffness means controlled resistance to collapse, not locking the knees or forcing the ankle, and show a lower-amplitude or slower-cadence option that preserves the identity."]},{"sectionKey":"coach_support","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8553457/","sourceTitle":"Application of Leg, Vertical, and Joint Stiffness in Running Performance: A Literature Overview","sourcePublisher":"Journal of Healthcare Engineering","sourceKind":"peer_reviewed_research","evidenceQuality":86,"claims":["Stiffness measures vary by task, speed, fatigue, maturity, and method, so coaches should not infer tendon or joint stiffness from appearance alone.","Provide side and rear observation, contact and distance counts, cadence or timing only when reliably measured, left-right comparison, surface and lane setup, phase placement, regression and progression rules, and a distinction between technical cueing and verified biomechanical measurement."]},{"sectionKey":"accessibility","sourceUrl":"https://www.nsca.com/globalassets/about/position-statements/position_stand_youth_resistance_training---2009.pdf","sourceTitle":"Youth Resistance Training: Updated Position Statement Paper From the NSCA","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":88,"claims":["Exercise selection and progression should match readiness, technical competence, supervision, equipment scale, and the individual's physical and psychosocial context.","Accessibility options include shorter lanes, slower cadence, supported ankle loading, no-flight ankling, fewer contacts, visual floor marks instead of a raised ladder, quieter settings, extra demonstration, and longer recovery without converting audience context into an exercise-card classification."]},{"sectionKey":"alternates","sourceUrl":"https://worldathletics.org/download/download?filename=152a49b1-8225-498e-8283-9c580dcd45d9.pdf&urlslug=Women%27s+100m+-+2017+IAAF+World+Championships+Biomechanical+report","sourceTitle":"Women's 100 m — 2017 IAAF World Championships Biomechanical Report","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":82,"claims":["A straight-leg shuffle into sprint is a compound drill progression, not merely a renamed stationary ankle hop.","Cadence, pass length, contact cap, and coaching intent are delivery annotations; stationary versus traveling, bilateral versus alternating, flight versus no flight, straight-leg bound versus march, ladder constraint, and a terminal sprint may require a controlled variant or distinct definition."]},{"sectionKey":"media","sourceUrl":"https://support.google.com/youtube/answer/171780?expand=PrivacyEnhancedMode&hl=en","sourceTitle":"Embed videos and playlists","sourcePublisher":"YouTube Help","sourceKind":"manufacturer_instruction","evidenceQuality":82,"claims":["YouTube supports privacy-enhanced embedding through youtube-nocookie.com.","The direct candidates for Straight-Leg Bound were discovered through visible YouTube search; current availability and embedding, exact movement identity and variant match, complete viewing, captions, instructional quality, safety, and approval remain separate review gates, and no candidate is approved by this packet."]}],"mediaCandidates":[{"url":"https://www.youtube.com/watch?v=NWL6Oo8VheA","title":"SPRINT DRILLS - Straight Leg Bound","channelName":"Trackwired","sourceQuery":"straight leg bound sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=RVl0cNJwTpo","title":"Straight Leg Bound (running drill)","channelName":"mandy mclane","sourceQuery":"straight leg bound sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=g1Wb9DbbO1g","title":"Straight Leg Bounds Running Form Drill Demonstration","channelName":"StrengthRunning","sourceQuery":"straight leg bound sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=MdxMFoABW-I","title":"Straight Leg Bound Running Drill","channelName":"Shane Niemeyer","sourceQuery":"straight leg bound sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=LxnGJ4Hcms8","title":"Straight Leg Bounds For Linear Speed","channelName":"overtimeathletes","sourceQuery":"straight leg bound sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."}],"alternateAssessments":[{"name":"Straight-Leg March","classification":"new_definition","rationale":"No-flight learning contacts materially reduce impact and require a distinct definition.","distinguishingDimensions":{"contactSequence":"march"}},{"name":"Straight-Leg Shuffle","classification":"new_variant","rationale":"Lower amplitude and cadence constraints create a controlled progression.","distinguishingDimensions":{"amplitude":"low"}},{"name":"Straight-Leg Bounds to Sprint","classification":"new_definition","rationale":"A terminal sprint transition changes intent, exposure, and space.","distinguishingDimensions":{"terminalAction":"sprint"}},{"name":"Straight-Leg Bound for Distance","classification":"modifier_annotation","rationale":"Maximal distance is a delivery intent if contact sequence is unchanged.","distinguishingDimensions":{"deliveryIntent":"horizontal_distance"}},{"name":"Bent-Knee Bounds","classification":"new_definition","rationale":"Greater knee cycle and projection strategy create a different bounding pattern.","distinguishingDimensions":{"kneeStrategy":"bent_knee"}}]}$packet$::JSONB),
    ('straight-leg-ankling-ladder','2026-07-25.7',$packet${"assessmentSummary":{"identity":"Straight-leg ankling or low-amplitude shuffle performed through a secured flat agility ladder that externally constrains contact spacing and sequence.","currentCardFindings":["The card does not specify whether one or two contacts occur in each box, so the ladder pattern is incomplete.","Its absolute-load value of 30 overstates the external load but its trip and coordination consequences are understated.","Visible search produced few exact ladder-ankling demonstrations; all media must remain unapproved and the card should be quarantined if an exact box sequence cannot be documented."],"proposedTaxonomy":{"movementPatterns":["straight_leg_ankling","externally_constrained_foot_placement"],"jointActions":["hip_flexion_extension","knee_extension_presentation","ankle_dorsiflexion","rapid_contact"],"planes":["sagittal"],"laterality":"alternating_left_right","intent":"precise_low_amplitude_contacts_at_defined_ladder_spacing"},"proposedAnatomy":{"primaryMuscles":["hamstrings","hip_flexors","soleus","gastrocnemius","tibialis_anterior"],"secondaryMuscles":["intrinsic_foot","quadriceps","gluteus_maximus","lumbopelvic_stabilizers"],"joints":["foot","ankle","knee","hip","lumbopelvic_complex","shoulder"]},"proposedDifficulty":{"technicalComplexity":54,"absoluteLoadDemand":18,"coordinationDemand":64,"supervisionDemand":46,"failureConsequence":40,"impact":28,"workCapacityDemand":24,"baseOverallDifficulty":54},"proposedLoadProfile":{"loadingType":"bodyweight_alternating_low_amplitude_ladder_constrained_locomotion","impactClass":"low_to_moderate","landingContactsPerRep":"define_one_or_two_contacts_per_box_and_total_boxes","primaryStress":["foot_placement_coordination","plantar_flexor_cyclic_load","visual_spatial_control"],"fatigueSensitivity":"missed_boxes_ladder_contacts_posture_and_contact_noise"},"proposedConstraints":{"requiredEquipment":["secured_flat_agility_ladder","clear_entry_and_exit"],"optionalEquipment":["video","alternative_flat_floor_marks"],"environment":["level_non_slip_surface","ladder_cannot_slide_or_curl"],"population":["can_walk_exact_pattern","pain_free_low_amplitude_contacts","can_stop_after_ladder"]},"proposedDosage":{"sets":"2-4_passes","contactsPerPass":"one_approved_pattern_over_6-12_boxes","restSeconds":"30-75","intensity":"precision_before_speed","progressWhen":"the athlete completes the exact pattern without touching the ladder or losing posture"},"proposedInstructions":{"coachCues":["State the box pattern first","Long leg, soft knee","Light contact in each target","Speed only after clean feet"],"athleteInstructions":["Follow the exact box sequence and slow down before your feet get messy"],"commonFaults":["undefined_pattern","looking_down_entire_pass","ladder_contact","locked_knee","racing"]},"proposedSafety":{"readiness":["walk_through_exact_pattern","secured_ladder","clear_exit"],"stopRules":["ladder_moves","repeated_missed_boxes","trip","pain","locked_knee_contact","unsafe_deceleration"]},"programmingDecision":"Retain only as a controlled external-constraint variant after defining the exact box sequence. Prefer flat marks when the ladder creates trip risk. Keep all media unapproved pending exact-pattern human review.","currentCardSnapshot":{"capturedAt":"2026-07-26T02:10:00.000Z","cardVersion":1,"status":"review","description":"Straight-Leg Ankling Ladder is a ladder-focused exercise for low-amplitude ankle stiffness and front-side foot strike awareness.","familyKey":"Ankle stiffness ladder","movementPatterns":[],"bodyRegions":[],"requiredEquipment":[],"optionalEquipment":[],"environment":{},"population":{},"difficulty":{"absoluteLoadDemand":30,"coordinationDemand":40,"technicalComplexity":40,"baseOverallDifficulty":40},"loadProfile":{},"fatigueProfile":{}}},"evidence":[{"sectionKey":"identity","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["World Athletics describes ankling as a progressive running drill that begins with learning a toe-to-ground loading action and then increases cadence.","Straight-Leg Ankling Ladder must state whether it is stationary or traveling, bilateral or alternating, walking, marching, dribbling, hopping, or bounding, its knee strategy, contact sequence, displacement, cadence, and terminal transition; spring or stiffness alone does not define identity."]},{"sectionKey":"taxonomy","sourceUrl":"https://worldathletics.org/download/download?filename=152a49b1-8225-498e-8283-9c580dcd45d9.pdf&urlslug=Women%27s+100m+-+2017+IAAF+World+Championships+Biomechanical+report","sourceTitle":"Women's 100 m — 2017 IAAF World Championships Biomechanical Report","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":82,"claims":["World Athletics treats straight-leg shuffle into sprinting as a drill progression that can be combined into a movement pattern congruent with the technical model.","Straight-Leg Ankling Ladder belongs to either low-amplitude cyclic plyometrics, sprint-mechanics locomotion, straight-leg shuffle or bound mechanics, or a compound transition; those categories must not be merged into one undifferentiated exercise."]},{"sectionKey":"anatomy","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/37989833/","sourceTitle":"Ankle and Plantar Flexor Muscle-Tendon Unit Function in Sprinters: A Narrative Review","sourcePublisher":"Sports Medicine","sourceKind":"peer_reviewed_research","evidenceQuality":89,"claims":["The ankle and plantar-flexor muscle-tendon units make phase-specific contributions to sprinting, with distinct roles for soleus and gastrocnemius and important energy transfer at maximum velocity.","The card should identify intrinsic foot, plantar-flexor, tibialis-anterior, knee-extensor, hamstring, hip-flexor and extensor, lumbopelvic, and arm-action roles according to the actual drill rather than labeling every drill ankle-only."]},{"sectionKey":"biomechanics","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8008308/","sourceTitle":"Kinematic Stride Characteristics of Maximal Sprint Running of Elite Sprinters – Verification of the Swing-Pull Technique","sourcePublisher":"Journal of Human Kinetics","sourceKind":"peer_reviewed_research","evidenceQuality":84,"claims":["Active foot contact with backswing velocity, small horizontal foot distance from the center of mass at contact, hip-extension velocity, and controlled support-leg flexion may help minimize braking during maximal sprinting.","Straight-Leg Ankling Ladder should cue contact close to the projected center of mass and observable rhythm without claiming that an isolated drill automatically reproduces or improves full-speed sprint mechanics."]},{"sectionKey":"difficulty","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8553457/","sourceTitle":"Application of Leg, Vertical, and Joint Stiffness in Running Performance: A Literature Overview","sourcePublisher":"Journal of Healthcare Engineering","sourceKind":"peer_reviewed_research","evidenceQuality":86,"claims":["Mechanical stiffness is task- and velocity-dependent, changes with fatigue, and represents coordinated whole-limb behavior rather than a fixed athlete trait.","Exercise difficulty must directly score technical complexity, physical and absolute-load demand, coordination, supervision, failure consequence, impact, work-capacity demand, and overall difficulty; audience labels are not part of exercise difficulty."]},{"sectionKey":"load_fatigue_recovery","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8938535/","sourceTitle":"Effects of Plyometric Training on Lower Body Muscle Architecture, Tendon Structure, Stiffness and Physical Performance: A Systematic Review and Meta-analysis","sourcePublisher":"Sports Medicine - Open","sourceKind":"peer_reviewed_research","evidenceQuality":91,"claims":["Plyometric training can change tendon stiffness and performance, so low-amplitude contacts still require progressive exposure and contact-volume accounting.","Straight-Leg Ankling Ladder needs total and per-leg contacts, lane distance, surface, footwear, amplitude, cadence or velocity, approach and transition distance, technical-fatigue markers, between-attempt recovery, and weekly impact accounting."]},{"sectionKey":"constraints","sourceUrl":"https://www.nsca.com/contentassets/116c55d64e1343d2b264e05aaf158a91/basics_of_strength_and_conditioning_manual.pdf","sourceTitle":"Basics of Strength and Conditioning Manual","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":84,"claims":["Plyometric and sprint drills require progressive preparation, safe surfaces and lanes, suitable footwear, spacing, recovery, and supervision matched to intensity and complexity.","The card should require a level, dry, non-slip lane with a deceleration zone when traveling; a secured ladder only for the ladder variant; and an athlete who can tolerate the selected contact amplitude without pain or compensatory mechanics."]},{"sectionKey":"dosage","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["World Athletics gives an example of two passes over 10 to 20 metres for ankling and related running drills, while instructing athletes to learn the movement before increasing pace.","Use passes, metres, seconds, and explicit contacts rather than ambiguous repetitions; low-skill learning passes may use walk-back recovery, while bounds and bound-to-sprint transitions need fuller recovery and immediate quality stops."]},{"sectionKey":"instructions","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8008308/","sourceTitle":"Kinematic Stride Characteristics of Maximal Sprint Running of Elite Sprinters – Verification of the Swing-Pull Technique","sourcePublisher":"Journal of Human Kinetics","sourceKind":"peer_reviewed_research","evidenceQuality":84,"claims":["Sprint-contact instruction should prioritize observable contact placement, active downward and backward foot velocity, posture, and rhythm rather than an unsupported promise of ideal technique.","Use a small task-specific cue set: stay stacked, keep steps short for ankling, contact close to the hips, preserve dorsiflexion without forcing a forefoot strike, let the heel behave naturally, and transition without reaching or locking the knee."]},{"sectionKey":"safety_stop_rules","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/37989833/","sourceTitle":"Ankle and Plantar Flexor Muscle-Tendon Unit Function in Sprinters: A Narrative Review","sourcePublisher":"Sports Medicine","sourceKind":"peer_reviewed_research","evidenceQuality":89,"claims":["Sprint plantar-flexor demand changes across start, acceleration, and maximum-velocity phases and should not be represented as uniformly low load.","Stop for foot, shin, calf, Achilles, hamstring, knee, hip, or back pain; loss of balance; repeated reaching or hard heel strike; locked-knee braking; loud or lengthening contacts; cadence drop; asymmetry; ladder displacement; or an unsafe sprint transition."]},{"sectionKey":"programming","sourceUrl":"https://worldathletics.org/download/download?filename=152a49b1-8225-498e-8283-9c580dcd45d9.pdf&urlslug=Women%27s+100m+-+2017+IAAF+World+Championships+Biomechanical+report","sourceTitle":"Women's 100 m — 2017 IAAF World Championships Biomechanical Report","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":82,"claims":["Sprint drills can progress from simpler to more complex tasks and combine into a sprint transition when the movement time and pattern fit the intended technical model.","Straight-Leg Ankling Ladder belongs after temperature and tissue preparation and before high-speed sprinting or high-output jumping; use learning versions in a mechanics block and bound or sprint-transition versions in a fresh output block."]},{"sectionKey":"athlete_support","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["Athlete support should show the exact movement at learning and performance cadence, the lane, contact sound, heel behavior, arm action, finish, and how a successful pass differs from merely moving the feet quickly.","Explain that stiffness means controlled resistance to collapse, not locking the knees or forcing the ankle, and show a lower-amplitude or slower-cadence option that preserves the identity."]},{"sectionKey":"coach_support","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8553457/","sourceTitle":"Application of Leg, Vertical, and Joint Stiffness in Running Performance: A Literature Overview","sourcePublisher":"Journal of Healthcare Engineering","sourceKind":"peer_reviewed_research","evidenceQuality":86,"claims":["Stiffness measures vary by task, speed, fatigue, maturity, and method, so coaches should not infer tendon or joint stiffness from appearance alone.","Provide side and rear observation, contact and distance counts, cadence or timing only when reliably measured, left-right comparison, surface and lane setup, phase placement, regression and progression rules, and a distinction between technical cueing and verified biomechanical measurement."]},{"sectionKey":"accessibility","sourceUrl":"https://www.nsca.com/globalassets/about/position-statements/position_stand_youth_resistance_training---2009.pdf","sourceTitle":"Youth Resistance Training: Updated Position Statement Paper From the NSCA","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":88,"claims":["Exercise selection and progression should match readiness, technical competence, supervision, equipment scale, and the individual's physical and psychosocial context.","Accessibility options include shorter lanes, slower cadence, supported ankle loading, no-flight ankling, fewer contacts, visual floor marks instead of a raised ladder, quieter settings, extra demonstration, and longer recovery without converting audience context into an exercise-card classification."]},{"sectionKey":"alternates","sourceUrl":"https://worldathletics.org/download/download?filename=152a49b1-8225-498e-8283-9c580dcd45d9.pdf&urlslug=Women%27s+100m+-+2017+IAAF+World+Championships+Biomechanical+report","sourceTitle":"Women's 100 m — 2017 IAAF World Championships Biomechanical Report","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":82,"claims":["A straight-leg shuffle into sprint is a compound drill progression, not merely a renamed stationary ankle hop.","Cadence, pass length, contact cap, and coaching intent are delivery annotations; stationary versus traveling, bilateral versus alternating, flight versus no flight, straight-leg bound versus march, ladder constraint, and a terminal sprint may require a controlled variant or distinct definition."]},{"sectionKey":"media","sourceUrl":"https://support.google.com/youtube/answer/171780?expand=PrivacyEnhancedMode&hl=en","sourceTitle":"Embed videos and playlists","sourcePublisher":"YouTube Help","sourceKind":"manufacturer_instruction","evidenceQuality":82,"claims":["YouTube supports privacy-enhanced embedding through youtube-nocookie.com.","The direct candidates for Straight-Leg Ankling Ladder were discovered through visible YouTube search; current availability and embedding, exact movement identity and variant match, complete viewing, captions, instructional quality, safety, and approval remain separate review gates, and no candidate is approved by this packet."]}],"mediaCandidates":[{"url":"https://www.youtube.com/watch?v=dlF9VDV-sJk","title":"Straight Leg Ankling","channelName":"TeamBuildr","sourceQuery":"straight leg ankling ladder drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=6zPCdZFU42Q","title":"Speed Ladder - Ankling","channelName":"Ultimate Athlete","sourceQuery":"straight leg ankling ladder drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=alnQKupHOqU","title":"Ankling Basic","channelName":"Tachyon TC","sourceQuery":"straight leg ankling ladder drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=em63lCvm9CM","title":"How to do One-Ins (Ladder Drill)","channelName":"National Academy of Sports Medicine","sourceQuery":"straight leg ankling ladder drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=9ZTRUVLjGzI","title":"10 Speed & Agility Ladder Drills For Fast Footwork & Quickness: Level 1","channelName":"I Know Football","sourceQuery":"straight leg ankling ladder drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."}],"alternateAssessments":[{"name":"Straight-Leg Ankling without Ladder","classification":"same_identity","rationale":"The fundamental movement is the same identity without a raised external constraint.","distinguishingDimensions":{"externalConstraint":"none"}},{"name":"Straight-Leg Ankling over Flat Marks","classification":"modifier_annotation","rationale":"Flat targets preserve spacing without ladder trip risk.","distinguishingDimensions":{"externalConstraint":"flat_marks"}},{"name":"One Contact per Box","classification":"modifier_annotation","rationale":"Contact sequence must be explicit but can remain a controlled pattern profile.","distinguishingDimensions":{"boxPattern":"one_in"}},{"name":"Two Contacts per Box","classification":"new_variant","rationale":"The added contact changes cadence and coordination.","distinguishingDimensions":{"boxPattern":"two_in"}},{"name":"Straight-Leg Bound","classification":"new_definition","rationale":"Open-lane repeated bounds have different amplitude, impact, and spacing.","distinguishingDimensions":{"externalConstraint":"open_lane"}}]}$packet$::JSONB),
    ('straight-leg-bounds-to-sprint','2026-07-25.7',$packet${"assessmentSummary":{"identity":"A compound high-speed drill consisting of a defined straight-leg bound or shuffle segment followed by a smooth transition into an upright sprint and controlled deceleration.","currentCardFindings":["The card is directionally correct but does not specify the number of bound contacts, transition criterion, sprint distance, target speed, or deceleration zone.","Its generic difficulty of 40 understates the compound coordination, hamstring exposure, impact, and space demands.","The current five-second work duration cannot communicate segment distance or cumulative sprint exposure."],"proposedTaxonomy":{"movementPatterns":["straight_leg_bound","transition_to_upright_sprint","controlled_deceleration"],"jointActions":["hip_flexion_extension","knee_extension_presentation","ankle_stiffness_regulation","sprint_cycle"],"planes":["sagittal","frontal"],"laterality":"alternating_left_right","intent":"preserve_contact_timing_during_transition_to_sprint"},"proposedAnatomy":{"primaryMuscles":["hamstrings","gluteus_maximus","soleus","gastrocnemius","hip_flexors"],"secondaryMuscles":["quadriceps","intrinsic_foot","tibialis_anterior","gluteus_medius","lumbopelvic_stabilizers","shoulder_girdle"],"joints":["foot","ankle","knee","hip","lumbopelvic_complex","shoulder"]},"proposedDifficulty":{"technicalComplexity":76,"absoluteLoadDemand":34,"coordinationDemand":80,"supervisionDemand":66,"failureConsequence":68,"impact":70,"workCapacityDemand":44,"baseOverallDifficulty":76},"proposedLoadProfile":{"loadingType":"bodyweight_compound_repeated_bound_to_high_speed_sprint","impactClass":"high","landingContactsPerRep":"define_bound_contacts_plus_sprint_steps_and_total_metres","primaryStress":["hamstring_high_speed_load","plantar_flexor_tendon_load","unilateral_contact_braking","sprint_neural_demand"],"fatigueSensitivity":"transition_reach_contact_noise_upright_speed_relaxation_and_deceleration"},"proposedConstraints":{"requiredEquipment":["30_to_50_metre_clear_lane","marked_bound_transition_sprint_and_deceleration_zones"],"optionalEquipment":["cones","timing_gates","video"],"environment":["level_dry_high_grip_surface","no_cross_traffic","suitable_footwear"],"population":["owns_straight_leg_bounds","recent_pain_free_fast_sprinting","can_decelerate_safely"]},"proposedDosage":{"sets":"2-4","attemptsPerSet":"1-2","segmentDose":"4-8_bound_contacts_then_10-20_metres_sprint_plus_deceleration","restSeconds":"150-300_between_high_speed_attempts","progressWhen":"the transition is smooth, sprint posture stays organized, and speed and contact quality repeat without symptoms"},"proposedInstructions":{"coachCues":["Long and quick through the bound","Transition gradually","Do not lunge into the sprint","Run tall and relax","Use the full shutdown zone"],"athleteInstructions":["Complete the assigned bound contacts, blend into a fast relaxed sprint, and decelerate through the marked zone"],"commonFaults":["locked_knee_bound","overreach","abrupt_transition","forced_first_sprint_step","insufficient_deceleration"]},"proposedSafety":{"readiness":["recent_fast_sprint_exposure","pain_free_straight_leg_bounds","full_clear_lane"],"stopRules":["hamstring_or_lower_limb_pain","locked_knee_braking","transition_stumble","speed_or_rhythm_drop","protective_mechanics","unsafe_shutdown"]},"programmingDecision":"Retain as a distinct compound definition, but require explicit bound contacts, transition and sprint distances, target intent, full recovery, and deceleration logistics. Do not use as a generic warm-up repetition.","currentCardSnapshot":{"capturedAt":"2026-07-26T02:10:00.000Z","cardVersion":1,"status":"review","description":"Straight-Leg Bounds to Sprint is a max velocity & rhythm exercise for speed, sprinting, and quick-release athletes. It emphasizes hip flexion extension, ankle stiffness, elastic ground contact while keeping the session intent aligned with the Vortex phase sequence.","familyKey":"Max Velocity Projection Drills","movementPatterns":[],"bodyRegions":[],"requiredEquipment":[],"optionalEquipment":[],"environment":{},"population":{},"difficulty":{"absoluteLoadDemand":30,"coordinationDemand":40,"technicalComplexity":40,"baseOverallDifficulty":40},"loadProfile":{},"fatigueProfile":{}}},"evidence":[{"sectionKey":"identity","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["World Athletics describes ankling as a progressive running drill that begins with learning a toe-to-ground loading action and then increases cadence.","Straight-Leg Bounds to Sprint must state whether it is stationary or traveling, bilateral or alternating, walking, marching, dribbling, hopping, or bounding, its knee strategy, contact sequence, displacement, cadence, and terminal transition; spring or stiffness alone does not define identity."]},{"sectionKey":"taxonomy","sourceUrl":"https://worldathletics.org/download/download?filename=152a49b1-8225-498e-8283-9c580dcd45d9.pdf&urlslug=Women%27s+100m+-+2017+IAAF+World+Championships+Biomechanical+report","sourceTitle":"Women's 100 m — 2017 IAAF World Championships Biomechanical Report","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":82,"claims":["World Athletics treats straight-leg shuffle into sprinting as a drill progression that can be combined into a movement pattern congruent with the technical model.","Straight-Leg Bounds to Sprint belongs to either low-amplitude cyclic plyometrics, sprint-mechanics locomotion, straight-leg shuffle or bound mechanics, or a compound transition; those categories must not be merged into one undifferentiated exercise."]},{"sectionKey":"anatomy","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/37989833/","sourceTitle":"Ankle and Plantar Flexor Muscle-Tendon Unit Function in Sprinters: A Narrative Review","sourcePublisher":"Sports Medicine","sourceKind":"peer_reviewed_research","evidenceQuality":89,"claims":["The ankle and plantar-flexor muscle-tendon units make phase-specific contributions to sprinting, with distinct roles for soleus and gastrocnemius and important energy transfer at maximum velocity.","The card should identify intrinsic foot, plantar-flexor, tibialis-anterior, knee-extensor, hamstring, hip-flexor and extensor, lumbopelvic, and arm-action roles according to the actual drill rather than labeling every drill ankle-only."]},{"sectionKey":"biomechanics","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8008308/","sourceTitle":"Kinematic Stride Characteristics of Maximal Sprint Running of Elite Sprinters – Verification of the Swing-Pull Technique","sourcePublisher":"Journal of Human Kinetics","sourceKind":"peer_reviewed_research","evidenceQuality":84,"claims":["Active foot contact with backswing velocity, small horizontal foot distance from the center of mass at contact, hip-extension velocity, and controlled support-leg flexion may help minimize braking during maximal sprinting.","Straight-Leg Bounds to Sprint should cue contact close to the projected center of mass and observable rhythm without claiming that an isolated drill automatically reproduces or improves full-speed sprint mechanics."]},{"sectionKey":"difficulty","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8553457/","sourceTitle":"Application of Leg, Vertical, and Joint Stiffness in Running Performance: A Literature Overview","sourcePublisher":"Journal of Healthcare Engineering","sourceKind":"peer_reviewed_research","evidenceQuality":86,"claims":["Mechanical stiffness is task- and velocity-dependent, changes with fatigue, and represents coordinated whole-limb behavior rather than a fixed athlete trait.","Exercise difficulty must directly score technical complexity, physical and absolute-load demand, coordination, supervision, failure consequence, impact, work-capacity demand, and overall difficulty; audience labels are not part of exercise difficulty."]},{"sectionKey":"load_fatigue_recovery","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8938535/","sourceTitle":"Effects of Plyometric Training on Lower Body Muscle Architecture, Tendon Structure, Stiffness and Physical Performance: A Systematic Review and Meta-analysis","sourcePublisher":"Sports Medicine - Open","sourceKind":"peer_reviewed_research","evidenceQuality":91,"claims":["Plyometric training can change tendon stiffness and performance, so low-amplitude contacts still require progressive exposure and contact-volume accounting.","Straight-Leg Bounds to Sprint needs total and per-leg contacts, lane distance, surface, footwear, amplitude, cadence or velocity, approach and transition distance, technical-fatigue markers, between-attempt recovery, and weekly impact accounting."]},{"sectionKey":"constraints","sourceUrl":"https://www.nsca.com/contentassets/116c55d64e1343d2b264e05aaf158a91/basics_of_strength_and_conditioning_manual.pdf","sourceTitle":"Basics of Strength and Conditioning Manual","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":84,"claims":["Plyometric and sprint drills require progressive preparation, safe surfaces and lanes, suitable footwear, spacing, recovery, and supervision matched to intensity and complexity.","The card should require a level, dry, non-slip lane with a deceleration zone when traveling; a secured ladder only for the ladder variant; and an athlete who can tolerate the selected contact amplitude without pain or compensatory mechanics."]},{"sectionKey":"dosage","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["World Athletics gives an example of two passes over 10 to 20 metres for ankling and related running drills, while instructing athletes to learn the movement before increasing pace.","Use passes, metres, seconds, and explicit contacts rather than ambiguous repetitions; low-skill learning passes may use walk-back recovery, while bounds and bound-to-sprint transitions need fuller recovery and immediate quality stops."]},{"sectionKey":"instructions","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8008308/","sourceTitle":"Kinematic Stride Characteristics of Maximal Sprint Running of Elite Sprinters – Verification of the Swing-Pull Technique","sourcePublisher":"Journal of Human Kinetics","sourceKind":"peer_reviewed_research","evidenceQuality":84,"claims":["Sprint-contact instruction should prioritize observable contact placement, active downward and backward foot velocity, posture, and rhythm rather than an unsupported promise of ideal technique.","Use a small task-specific cue set: stay stacked, keep steps short for ankling, contact close to the hips, preserve dorsiflexion without forcing a forefoot strike, let the heel behave naturally, and transition without reaching or locking the knee."]},{"sectionKey":"safety_stop_rules","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/37989833/","sourceTitle":"Ankle and Plantar Flexor Muscle-Tendon Unit Function in Sprinters: A Narrative Review","sourcePublisher":"Sports Medicine","sourceKind":"peer_reviewed_research","evidenceQuality":89,"claims":["Sprint plantar-flexor demand changes across start, acceleration, and maximum-velocity phases and should not be represented as uniformly low load.","Stop for foot, shin, calf, Achilles, hamstring, knee, hip, or back pain; loss of balance; repeated reaching or hard heel strike; locked-knee braking; loud or lengthening contacts; cadence drop; asymmetry; ladder displacement; or an unsafe sprint transition."]},{"sectionKey":"programming","sourceUrl":"https://worldathletics.org/download/download?filename=152a49b1-8225-498e-8283-9c580dcd45d9.pdf&urlslug=Women%27s+100m+-+2017+IAAF+World+Championships+Biomechanical+report","sourceTitle":"Women's 100 m — 2017 IAAF World Championships Biomechanical Report","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":82,"claims":["Sprint drills can progress from simpler to more complex tasks and combine into a sprint transition when the movement time and pattern fit the intended technical model.","Straight-Leg Bounds to Sprint belongs after temperature and tissue preparation and before high-speed sprinting or high-output jumping; use learning versions in a mechanics block and bound or sprint-transition versions in a fresh output block."]},{"sectionKey":"athlete_support","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["Athlete support should show the exact movement at learning and performance cadence, the lane, contact sound, heel behavior, arm action, finish, and how a successful pass differs from merely moving the feet quickly.","Explain that stiffness means controlled resistance to collapse, not locking the knees or forcing the ankle, and show a lower-amplitude or slower-cadence option that preserves the identity."]},{"sectionKey":"coach_support","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8553457/","sourceTitle":"Application of Leg, Vertical, and Joint Stiffness in Running Performance: A Literature Overview","sourcePublisher":"Journal of Healthcare Engineering","sourceKind":"peer_reviewed_research","evidenceQuality":86,"claims":["Stiffness measures vary by task, speed, fatigue, maturity, and method, so coaches should not infer tendon or joint stiffness from appearance alone.","Provide side and rear observation, contact and distance counts, cadence or timing only when reliably measured, left-right comparison, surface and lane setup, phase placement, regression and progression rules, and a distinction between technical cueing and verified biomechanical measurement."]},{"sectionKey":"accessibility","sourceUrl":"https://www.nsca.com/globalassets/about/position-statements/position_stand_youth_resistance_training---2009.pdf","sourceTitle":"Youth Resistance Training: Updated Position Statement Paper From the NSCA","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":88,"claims":["Exercise selection and progression should match readiness, technical competence, supervision, equipment scale, and the individual's physical and psychosocial context.","Accessibility options include shorter lanes, slower cadence, supported ankle loading, no-flight ankling, fewer contacts, visual floor marks instead of a raised ladder, quieter settings, extra demonstration, and longer recovery without converting audience context into an exercise-card classification."]},{"sectionKey":"alternates","sourceUrl":"https://worldathletics.org/download/download?filename=152a49b1-8225-498e-8283-9c580dcd45d9.pdf&urlslug=Women%27s+100m+-+2017+IAAF+World+Championships+Biomechanical+report","sourceTitle":"Women's 100 m — 2017 IAAF World Championships Biomechanical Report","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":82,"claims":["A straight-leg shuffle into sprint is a compound drill progression, not merely a renamed stationary ankle hop.","Cadence, pass length, contact cap, and coaching intent are delivery annotations; stationary versus traveling, bilateral versus alternating, flight versus no flight, straight-leg bound versus march, ladder constraint, and a terminal sprint may require a controlled variant or distinct definition."]},{"sectionKey":"media","sourceUrl":"https://support.google.com/youtube/answer/171780?expand=PrivacyEnhancedMode&hl=en","sourceTitle":"Embed videos and playlists","sourcePublisher":"YouTube Help","sourceKind":"manufacturer_instruction","evidenceQuality":82,"claims":["YouTube supports privacy-enhanced embedding through youtube-nocookie.com.","The direct candidates for Straight-Leg Bounds to Sprint were discovered through visible YouTube search; current availability and embedding, exact movement identity and variant match, complete viewing, captions, instructional quality, safety, and approval remain separate review gates, and no candidate is approved by this packet."]}],"mediaCandidates":[{"url":"https://www.youtube.com/watch?v=xwbmyicxBRw","title":"Straight Leg Bound to Sprint","channelName":"BoostYourGame","sourceQuery":"straight leg bound sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=KFX5AuLYFbU","title":"Straight Leg Bound to Sprint","channelName":"Unapproved visible-search candidate","sourceQuery":"straight leg bound sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=io6GBTk15yQ","title":"Straight leg bound to sprint | HansenAthletics Online","channelName":"HansenAthletics Online","sourceQuery":"straight leg bound sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=_oigi9EIKVI","title":"Straight Leg Bound To Sprint Drill To Improve Foot Strike","channelName":"Unapproved visible-search candidate","sourceQuery":"straight leg bound sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=eapcBeaHvP4","title":"Straight Leg Bound 20 Sprint 20","channelName":"Unapproved visible-search candidate","sourceQuery":"straight leg bound sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."}],"alternateAssessments":[{"name":"Straight-Leg Bound","classification":"new_definition","rationale":"The no-transition bound is the prerequisite base exercise and a distinct definition.","distinguishingDimensions":{"terminalAction":"run_out"}},{"name":"Straight-Leg Shuffle to Sprint","classification":"new_variant","rationale":"Lower-amplitude shuffle contacts reduce impact but preserve the transition.","distinguishingDimensions":{"entryPattern":"shuffle"}},{"name":"4 Contacts to 10 m Sprint","classification":"modifier_annotation","rationale":"Contact and sprint distance are dosage variables.","distinguishingDimensions":{"boundContacts":4,"sprintDistanceMetres":10}},{"name":"8 Contacts to 20 m Sprint","classification":"modifier_annotation","rationale":"A longer exposure is a dosage progression, not a new identity.","distinguishingDimensions":{"boundContacts":8,"sprintDistanceMetres":20}},{"name":"Straight-Leg Bound to Fly Zone","classification":"new_variant","rationale":"A timed or measured fly zone adds testing logistics and higher speed exposure.","distinguishingDimensions":{"terminalAction":"timed_fly"}}]}$packet$::JSONB),
    ('wall-ankling-pogo','2026-07-25.8',$packet${"assessmentSummary":{"identity":"Unresolved wall-supported repeated-contact drill whose body angle, support force, bilateral or unilateral takeoff and landing, alternating or same-leg sequence, cadence, amplitude, and displacement are not defined by the current card.","currentCardFindings":["The description contains broken generated grammar and incorrectly frames the drill as a direct jump-height exercise.","The name combines ankling and pogo without specifying whether the athlete alternates contacts, repeats on one leg, or hops bilaterally.","Two sets of three repetitions and five seconds conflict as dose units, while the generic jump instructions do not describe wall setup or exact contacts."],"proposedTaxonomy":{"movementPatterns":["unresolved_wall_supported_repeated_contact"],"jointActions":["unresolved_pending_contact_sequence"],"planes":["sagittal"],"laterality":"unresolved","intent":"unresolved_between_supported_single_leg_pogo_alternating_stride_pogo_and_wall_ankling"},"proposedAnatomy":{"primaryMuscles":["unresolved_pending_identity"],"secondaryMuscles":["unresolved_pending_identity"],"joints":["foot","ankle","knee","hip","lumbopelvic_complex","shoulder","wrist"]},"proposedDifficulty":{"technicalComplexity":46,"absoluteLoadDemand":24,"coordinationDemand":52,"supervisionDemand":50,"failureConsequence":40,"impact":38,"workCapacityDemand":25,"baseOverallDifficulty":46},"proposedLoadProfile":{"loadingType":"unresolved_bodyweight_wall_supported_repeated_contact","impactClass":"unresolved_low_to_moderate","landingContactsPerRep":"must_be_defined_before_use","primaryStress":["foot_and_ankle_cyclic_load","upper_body_support","postural_control"],"fatigueSensitivity":"cannot_be_calibrated_until_body_angle_laterality_and_contact_sequence_are_resolved"},"proposedConstraints":{"requiredEquipment":["immovable_non_slip_wall_or_rack","human_identity_review","safe_footing"],"optionalEquipment":["video"],"environment":["quarantined_from_generation"],"population":["none_until_identity_is_resolved"]},"proposedDosage":{"sets":"not_prescribable","contactsPerSet":"not_prescribable","restSeconds":"not_prescribable","intensity":"not_prescribable","progressWhen":"body angle, hand position, support force, laterality, contact sequence, amplitude, and cadence are approved"},"proposedInstructions":{"coachCues":["Do not coach from the current card","Select one exact supported contact pattern first"],"athleteInstructions":["Use an exact demonstrated supported pogo or wall sprint drill instead"],"commonFaults":["undefined_laterality","undefined_body_angle","mixing_ankling_and_pogo","unstable_wall","generic_jump_template"]},"proposedSafety":{"readiness":["human_identity_adjudication","verified_immovable_support"],"stopRules":["do_not_generate_or_prescribe"]},"programmingDecision":"Quarantine. If contacts repeat on one leg, author Wall-Supported Single-Leg Pogo; if they alternate in place, author Wall-Supported Alternating Stride Pogo; if there is no flight, merge the useful support constraint into a wall ankling or march variant.","currentCardSnapshot":{"capturedAt":"2026-07-26T03:15:00.000Z","cardVersion":1,"status":"review","description":"The athlete performs Wall Ankling Pogo as a quality-first jump-height drill, emphasizing the wall support lets athletes feel active foot strike and lower-leg stiffness with less balance noise.","familyKey":"Supported sprint stiffness","movementPatterns":[],"bodyRegions":[],"requiredEquipment":[],"optionalEquipment":[],"environment":{},"population":{},"difficulty":{"absoluteLoadDemand":10,"coordinationDemand":40,"technicalComplexity":40,"baseOverallDifficulty":40},"loadProfile":{},"fatigueProfile":{}}},"evidence":[{"sectionKey":"identity","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["World Athletics presents ankling and progressively larger knee actions as distinct drill constraints that are learned before cadence increases.","Wall Ankling Pogo must state the cyclic recovery height, contact sequence, displacement, cadence, arm action, approach, transition, sprint segment, and deceleration; low, high, build, bleed, and run are not interchangeable labels."]},{"sectionKey":"taxonomy","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6872694/","sourceTitle":"The Training and Development of Elite Sprint Performance: an Integration of Scientific and Best Practice Literature","sourcePublisher":"Sports Medicine - Open","sourceKind":"peer_reviewed_research","evidenceQuality":90,"claims":["Maximal sprint performance involves interacting spatiotemporal, segment-configuration, segment-velocity, and front- and back-side variables rather than one isolated technical feature.","Wall Ankling Pogo belongs to a traveling alternating dribble family, a controlled recovery-height variant, a supported repeated-contact family, or a compound drill-to-sprint transition; it is not itself a maximal sprint."]},{"sectionKey":"anatomy","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/37989833/","sourceTitle":"Ankle and Plantar Flexor Muscle-Tendon Unit Function in Sprinters: A Narrative Review","sourcePublisher":"Sports Medicine","sourceKind":"peer_reviewed_research","evidenceQuality":89,"claims":["The ankle and plantar-flexor muscle-tendon units contribute differently across sprint phases, with soleus and gastrocnemius supporting and accelerating the center of mass and transferring energy at high speed.","The card should include intrinsic-foot, soleus, gastrocnemius, tibialis-anterior, hamstring, quadriceps, hip-flexor and extensor, pelvic-stabilizer, trunk, and arm-action roles in proportion to recovery height and running speed."]},{"sectionKey":"biomechanics","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11994691/","sourceTitle":"Angular kinematics during top speed sprinting in male intercollegiate track and field and team sport athletes","sourcePublisher":"Sports Biomechanics","sourceKind":"peer_reviewed_research","evidenceQuality":85,"claims":["Top-speed sprinting depends on coordinated lower-extremity angular behavior, and observed strategies differ between populations and sporting demands.","A dribble drill can constrain foot-path size, cadence, and contact placement, but its appearance cannot prove sprint force, joint stiffness, or transfer; observable quality should focus on compact cycling, contact close to the projected center of mass, posture, relaxation, and smooth transition."]},{"sectionKey":"difficulty","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8553457/","sourceTitle":"Application of Leg, Vertical, and Joint Stiffness in Running Performance: A Literature Overview","sourcePublisher":"Journal of Healthcare Engineering","sourceKind":"peer_reviewed_research","evidenceQuality":86,"claims":["Mechanical stiffness varies with task, velocity, maturity, fatigue, and measurement method and should not be inferred as a fixed property from drill appearance.","Exercise difficulty must directly score technical complexity, physical and absolute-load demand, coordination, supervision, failure consequence, impact, work-capacity demand, and overall difficulty; audience experience remains programming context."]},{"sectionKey":"load_fatigue_recovery","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/37989833/","sourceTitle":"Ankle and Plantar Flexor Muscle-Tendon Unit Function in Sprinters: A Narrative Review","sourcePublisher":"Sports Medicine","sourceKind":"peer_reviewed_research","evidenceQuality":89,"claims":["Plantar-flexor and ankle demands change as a sprint progresses from start through acceleration to maximal velocity.","Wall Ankling Pogo needs pass length, total steps or contacts, cycle height, cadence or speed intent, sprint metres when present, surface, footwear, weekly high-speed exposure, technical-fatigue thresholds, and between-attempt recovery."]},{"sectionKey":"constraints","sourceUrl":"https://www.nsca.com/globalassets/education/nsca-coach/nsca-coach-5.4.pdf","sourceTitle":"Developing Linear Speed","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":82,"claims":["Linear-speed work requires suitable space, clear start and finish zones, progressive intensity, adequate recovery, and coaching that preserves the session's speed intent.","Require a level, dry, non-slip lane; clear entry, finish, and deceleration zones; safe athlete spacing; suitable footwear; an immovable support only for supported variants; and readiness for the highest speed actually prescribed."]},{"sectionKey":"dosage","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["World Athletics gives two passes over 10 to 20 metres as an example for progressive sprint drills and directs athletes to learn the movement before increasing cadence.","Use passes, metres, contact counts, cycle height, target intensity, and full recovery rather than a generic work interval; transition drills must separately prescribe drill, sprint, and deceleration distances."]},{"sectionKey":"instructions","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8008308/","sourceTitle":"Kinematic Stride Characteristics of Maximal Sprint Running of Elite Sprinters – Verification of the Swing-Pull Technique","sourcePublisher":"Journal of Human Kinetics","sourceKind":"peer_reviewed_research","evidenceQuality":84,"claims":["Small horizontal foot distance from the center of mass at contact, active foot velocity before contact, and coordinated hip motion may help minimize braking during maximal sprinting.","Use a small observable cue set: make a compact circle, recover to the assigned height, step close beneath the hips, stay stacked and relaxed, keep the arms coordinated, increase cadence without reaching, and blend rather than lunge into a sprint."]},{"sectionKey":"safety_stop_rules","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6872694/","sourceTitle":"The Training and Development of Elite Sprint Performance: an Integration of Scientific and Best Practice Literature","sourcePublisher":"Sports Medicine - Open","sourceKind":"peer_reviewed_research","evidenceQuality":90,"claims":["Sprint power demand rises steeply with velocity, so drill-to-sprint transitions should be treated as high-speed exposures rather than low-load warm-up repetitions.","Stop for foot, shin, calf, Achilles, hamstring, knee, hip, or back pain; a limp; repeated reaching or locked-knee braking; loud or lengthening contacts; cadence or speed loss; rising tension; unsafe support movement; an abrupt transition; or inadequate deceleration space."]},{"sectionKey":"programming","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/36513077/","sourceTitle":"Effect of Vertical Jump and Sprint Training on Power and Speed Performance Transfer","sourcePublisher":"Motor Control","sourceKind":"peer_reviewed_research","evidenceQuality":88,"claims":["Training transfer depends on the relationship between the practiced task, performance outcome, population, dose, and intervention rather than similarity of one visible feature.","Wall Ankling Pogo belongs after general preparation and before maximal sprinting: use low and high dribbles for a named coordination constraint, and use dribble-to-sprint only as a fresh high-speed exposure when the athlete already owns both segments."]},{"sectionKey":"athlete_support","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["Athlete support should show the movement first at learning cadence and then at the prescribed speed.","Show side and rear views, the ankle-, shin-, or knee-height recovery target, contact zone, lane and finish, arm rhythm, transition, deceleration, and a lower-cadence option; explain that fast feet do not justify longer reaches or forced foot strike."]},{"sectionKey":"coach_support","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11994691/","sourceTitle":"Angular kinematics during top speed sprinting in male intercollegiate track and field and team sport athletes","sourcePublisher":"Sports Biomechanics","sourceKind":"peer_reviewed_research","evidenceQuality":85,"claims":["Sprint kinematics can differ across athlete populations, so one visual template should not be treated as universal proof of efficiency.","Provide side and rear observation, exact cycle-height definitions, pass and contact counts, optional video or timing, left-right comparison, relaxation and posture checks, lane setup, recovery, progression criteria, and a clear distinction between a drill cue and measured sprint biomechanics."]},{"sectionKey":"accessibility","sourceUrl":"https://www.nsca.com/globalassets/about/position-statements/position_stand_youth_resistance_training---2009.pdf","sourceTitle":"Youth Resistance Training: Updated Position Statement Paper From the NSCA","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":88,"claims":["Exercise selection and progression should match readiness, technical competence, supervision, equipment scale, and the individual's physical and psychosocial context.","Accessibility options include slower cadence, shorter lanes, lower recovery height, walking cycles, flat contact targets, a stable support, fewer contacts, longer recovery, quieter instruction, and removing the sprint transition while keeping difficulty dimensions explicit."]},{"sectionKey":"alternates","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6872694/","sourceTitle":"The Training and Development of Elite Sprint Performance: an Integration of Scientific and Best Practice Literature","sourcePublisher":"Sports Medicine - Open","sourceKind":"peer_reviewed_research","evidenceQuality":90,"claims":["Sprint performance emerges from interacting mechanics and cannot be reduced to one preferred recovery height or cue.","Ankle-, shin-, calf-, and knee-height dribbles are controlled recovery-height variants of one cyclic pattern; cadence, lane length, and arm constraint are delivery annotations; a terminal sprint or a materially different supported contact sequence requires a distinct variant or definition."]},{"sectionKey":"media","sourceUrl":"https://support.google.com/youtube/answer/171780?expand=PrivacyEnhancedMode&hl=en","sourceTitle":"Embed videos and playlists","sourcePublisher":"YouTube Help","sourceKind":"manufacturer_instruction","evidenceQuality":82,"claims":["YouTube supports privacy-enhanced embedding through youtube-nocookie.com.","The direct candidates for Wall Ankling Pogo were discovered through visible YouTube search; current availability and embedding, exact cycle height and contact sequence, complete viewing, captions, instructional quality, safety, and approval remain separate review gates, and no candidate is approved by this packet."]}],"mediaCandidates":[{"url":"https://www.youtube.com/watch?v=uLagcbggFjs","title":"Wall Drill SL Pogo","channelName":"Kinetic | Sports Physical Therapy | Delafield, WI","sourceQuery":"wall ankling pogo sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=esHx4r6hFzQ","title":"Wall Stride Pogos","channelName":"Unapproved visible-search candidate","sourceQuery":"wall ankling pogo sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=tnwd7N6-bl0","title":"Uni-lateral Ankling (Pogos)","channelName":"Elite Performance “Elite” Co.","sourceQuery":"wall ankling pogo sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=uoEykHhldnQ","title":"Alternate Pogos (Ankling) Run Drill","channelName":"oli.physio","sourceQuery":"wall ankling pogo sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."},{"url":"https://www.youtube.com/watch?v=LetpJhFP7GE","title":"Pogos & Ankling","channelName":"Bespoke Conditioning","sourceQuery":"wall ankling pogo sprint drill","linkStatus":"unverified","embeddingAllowed":false,"externalVerification":null,"notes":"Candidate discovered for human review; availability, embedding, exact-version match, content, accessibility, and demonstration quality remain pending."}],"alternateAssessments":[{"name":"Wall-Supported Single-Leg Pogo","classification":"reject","rationale":"Do not create until human review confirms repeated same-leg contacts and exact body angle.","distinguishingDimensions":{"contactSequence":"same_leg_repeated"}},{"name":"Wall-Supported Alternating Stride Pogo","classification":"reject","rationale":"Do not create until human review confirms alternating flight contacts and exact support setup.","distinguishingDimensions":{"contactSequence":"alternating"}},{"name":"Wall Ankling without Flight","classification":"reject","rationale":"Do not merge until human review confirms a no-flight ankle-loading pattern.","distinguishingDimensions":{"contactSequence":"no_flight"}},{"name":"Free Single-Leg Pogo","classification":"new_definition","rationale":"Removing wall support materially increases balance and postural demand.","distinguishingDimensions":{"support":"none"}},{"name":"Wall Drill March","classification":"new_definition","rationale":"A deliberate supported march has no repeated flight and a different contact sequence.","distinguishingDimensions":{"contactSequence":"march"}}]}$packet$::JSONB);
  -- END GENERATED CANONICAL RESEARCH PACKETS

  UPDATE coaching.exercise_definition_v1 definition
  SET description=packet.packet_json#>>'{assessmentSummary,identity}',
    family_key='ankling_straight_leg_drills',
    card_version=CASE WHEN already_applied_count=0
      THEN definition.card_version+1 ELSE definition.card_version END,
    status='review',
    content_confidence=CASE
      WHEN definition.slug=ANY(selectable_slugs) THEN 76 ELSE 52 END,
    scoring_confidence=CASE
      WHEN definition.slug=ANY(selectable_slugs) THEN 66 ELSE 50 END,
    media_confidence=20,
    movement_patterns=ARRAY(SELECT jsonb_array_elements_text(
      packet.packet_json#>'{assessmentSummary,proposedTaxonomy,movementPatterns}')),
    body_regions=ARRAY(SELECT jsonb_array_elements_text(
      packet.packet_json#>'{assessmentSummary,proposedAnatomy,joints}')),
    required_equipment=ARRAY(SELECT jsonb_array_elements_text(
      packet.packet_json#>'{assessmentSummary,proposedConstraints,requiredEquipment}')),
    optional_equipment=ARRAY(SELECT jsonb_array_elements_text(
      packet.packet_json#>'{assessmentSummary,proposedConstraints,optionalEquipment}')),
    anatomy_json=jsonb_build_object(
      'primaryMusclesAndTissues',
        packet.packet_json#>'{assessmentSummary,proposedAnatomy,primaryMuscles}',
      'secondaryMusclesAndTissues',
        packet.packet_json#>'{assessmentSummary,proposedAnatomy,secondaryMuscles}',
      'joints',packet.packet_json#>'{assessmentSummary,proposedAnatomy,joints}',
      'actions',packet.packet_json#>'{assessmentSummary,proposedTaxonomy,jointActions}',
      'planes',packet.packet_json#>'{assessmentSummary,proposedTaxonomy,planes}',
      'laterality',packet.packet_json#>>'{assessmentSummary,proposedTaxonomy,laterality}',
      'intent',packet.packet_json#>>'{assessmentSummary,proposedTaxonomy,intent}'),
    environment_json=jsonb_build_object(
      'requirements',packet.packet_json#>'{assessmentSummary,proposedConstraints,environment}',
      'surfacePolicy','dry_level_non_slip_surface_appropriate_to_contact_intensity',
      'trafficPolicy','clear_station_or_one_directional_lane_with_safe_finish',
      'weatherPolicy','reduce_or_replace_when_traction_visibility_or_spacing_is_unreliable',
      'humanReviewRequired',TRUE),
    population_json=jsonb_build_object(
      'selectionStatus','candidate_requires_human_review',
      'readinessChecks',packet.packet_json#>'{assessmentSummary,proposedConstraints,population}',
      'structurallyPrescribable',definition.slug=ANY(selectable_slugs),
      'identitySequenceResolved',definition.slug=ANY(selectable_slugs),
      'constraints',jsonb_build_array(
        'scale_from_current_readiness_and_movement_competence',
        'pain_symptoms_surface_lane_and_fatigue_override_the_planned_dose',
        'do_not_infer_athlete_proficiency_from_exercise_difficulty'),
      'contraindications',jsonb_build_array(
        'sharp_or_increasing_pain','limp_or_repeated_balance_loss',
        'unsafe_surface_lane_finish_or_equipment',
        'inability_to_follow_the_declared_contact_sequence')),
    athlete_support_json=jsonb_build_object(
      'plainLanguageSummary',packet.packet_json#>'{assessmentSummary,proposedInstructions,athleteInstructions}',
      'setupChecklist',jsonb_build_array(
        'confirm_surface_lane_contact_pattern_and_finish',
        'rehearse_below_training_speed','confirm_stop_signal_and_safe_exit'),
      'cues',packet.packet_json#>'{assessmentSummary,proposedInstructions,coachCues}',
      'expectedSensations',packet.packet_json#>'{assessmentSummary,proposedLoadProfile,primaryStress}',
      'stopSignals',packet.packet_json#>'{assessmentSummary,proposedSafety,stopRules}',
      'readinessChecks',packet.packet_json#>'{assessmentSummary,proposedSafety,readiness}',
      'feedbackPrompt','Were contacts quiet, close, symmetric or correctly alternating, pain-free, and repeatable through the declared finish?',
      'accessibilityOptions',jsonb_build_array(
        'shorter_lane_or_fewer_contacts','slower_cadence','lower_amplitude',
        'flat_visual_marks_instead_of_ladder','extra_demonstration',
        'longer_recovery','live_written_still_image_or_video_instruction')),
    coach_support_json=jsonb_build_object(
      'identityContract',packet.packet_json#>>'{assessmentSummary,identity}',
      'programmingDecision',packet.packet_json#>>'{assessmentSummary,programmingDecision}',
      'coachCues',packet.packet_json#>'{assessmentSummary,proposedInstructions,coachCues}',
      'commonFaults',packet.packet_json#>'{assessmentSummary,proposedInstructions,commonFaults}',
      'qualityGate',packet.packet_json#>>'{assessmentSummary,proposedDosage,progressWhen}',
      'stopRules',packet.packet_json#>'{assessmentSummary,proposedSafety,stopRules}',
      'observationPlan',jsonb_build_array(
        'rear_view_for_lane_symmetry_and_frontal_control',
        'side_view_for_posture_contact_location_flight_and_reach',
        'first_to_last_contact_comparison_for_fatigue_drift'),
      'cumulativeBudgetWarnings',jsonb_build_array(
        'count_every_landing_contact_and_each_side',
        'count_prior_sprinting_jumping_pogo_and_lower_leg_exposure',
        'high_speed_and_high_impact_cards_require_full_quality_recovery'),
      'escalation',jsonb_build_object(
        'clinical','stop_and_refer_when_pain_neurologic_symptoms_or_limp_persist',
        'emergency','follow_facility_emergency_plan_for_acute_injury_or_collapse')),
    support_operations_json=jsonb_build_object(
      'stationType',CASE WHEN definition.slug='ankle-pogo-in-place'
        THEN 'stationary_contact_station' ELSE 'one_directional_drill_lane' END,
      'requiredEquipment',packet.packet_json#>'{assessmentSummary,proposedConstraints,requiredEquipment}',
      'optionalEquipment',packet.packet_json#>'{assessmentSummary,proposedConstraints,optionalEquipment}',
      'environment',packet.packet_json#>'{assessmentSummary,proposedConstraints,environment}',
      'dosage',packet.packet_json#>'{assessmentSummary,proposedDosage}',
      'contactAccounting',packet.packet_json#>>'{assessmentSummary,proposedLoadProfile,landingContactsPerRep}',
      'structuralSelectionAllowed',definition.slug=ANY(selectable_slugs),
      'selectionBlockReason',CASE WHEN definition.slug=ANY(selectable_slugs)
        THEN NULL ELSE packet.packet_json#>>'{assessmentSummary,programmingDecision}' END,
      'groupFlow',jsonb_build_object(
        'oneAthletePerStationOrLane',TRUE,'staggeredStarts',TRUE,
        'clearFinishBeforeNextStart',TRUE,'coachMustSeeSetupAndFinish',TRUE),
      'recording',jsonb_build_array(
        'selected_identity_and_profile','distance_time_or_contacts_per_side',
        'contact_pattern','surface_and_spacing','rest','quality_failures','symptoms'),
      'humanReviewRequired',TRUE),
    approved_video_url=NULL,reviewed_by=NULL,approved_by=NULL,last_reviewed_at=NULL,
    provenance_json=definition.provenance_json||jsonb_build_object(
      'researchCompletionMigration',migration_key,
      'researchBatch',research_batch,'researchVersion',packet.research_version,
      'auditedSourceSlugs',jsonb_build_array(
        'ankle-pogo-in-place','low-pogos','ankling-pogo-hop',
        'ankling-dribble-march','ankling-drill','ankling-walk',
        'fast-ankling-pogo-march','distance-jump-ankle-pogo-in-place',
        'distance-jump-straight-leg-bound-march','straight-leg-bound-march',
        'distance-jump-straight-leg-bound','straight-leg-ankling-ladder',
        'straight-leg-bounds-to-sprint','wall-ankling-pogo'),
      'identityAuthorityMigrations',jsonb_build_array(
        '339_coaching_high_confidence_implement_identity_consolidation',
        '392_coaching_score_74_variant_identity_consolidations',
        '396_coaching_score_72_variant_identity_consolidations',
        '412_coaching_ankling_straight_leg_identity_lineage_correction'),
      'difficultyModel','max_exercise_complexity_physical_difficulty',
      'evidenceState','candidate_requires_human_review',
      'mediaState','public_candidates_unverified_and_non_embeddable',
      'humanReviewRequired',TRUE,'publicationQuarantined',TRUE,
      'cardApprovalCreated',FALSE,'mediaApprovalCreated',FALSE,
      'graphApprovalCreated',FALSE,'calibrationApprovalCreated',FALSE),
    updated_at=now()
  FROM family_packet_seed packet
  WHERE definition.facility_id=1 AND definition.slug=packet.definition_slug
    AND definition.status<>'archived';

  UPDATE coaching.exercise_variant_v1 variant
  SET difficulty_json=packet.packet_json#>'{assessmentSummary,proposedDifficulty}',
    requirements_json=jsonb_build_object(
      'requiredEquipment',packet.packet_json#>'{assessmentSummary,proposedConstraints,requiredEquipment}',
      'optionalEquipment',packet.packet_json#>'{assessmentSummary,proposedConstraints,optionalEquipment}',
      'environment',packet.packet_json#>'{assessmentSummary,proposedConstraints,environment}',
      'population',packet.packet_json#>'{assessmentSummary,proposedConstraints,population}',
      'readiness',packet.packet_json#>'{assessmentSummary,proposedSafety,readiness}',
      'structurallySelectable',definition.slug=ANY(selectable_slugs),
      'selectable',definition.slug=ANY(selectable_slugs),
      'identitySequenceResolved',definition.slug=ANY(selectable_slugs),
      'selectionBlockReason',CASE WHEN definition.slug=ANY(selectable_slugs)
        THEN NULL ELSE packet.packet_json#>>'{assessmentSummary,programmingDecision}' END,
      'humanReviewRequired',TRUE),
    load_profile_json=(packet.packet_json#>'{assessmentSummary,proposedLoadProfile}')
      ||jsonb_build_object(
        'loadSource','bodyweight_and_declared_external_constraints',
        'contactBudgetRequired',TRUE,'humanReviewRequired',TRUE),
    fatigue_profile_json=jsonb_build_object(
      'fatigueSensitivity',packet.packet_json#>>'{assessmentSummary,proposedLoadProfile,fatigueSensitivity}',
      'primaryStress',packet.packet_json#>'{assessmentSummary,proposedLoadProfile,primaryStress}',
      'impactClass',packet.packet_json#>>'{assessmentSummary,proposedLoadProfile,impactClass}',
      'monitor',packet.packet_json#>'{assessmentSummary,proposedInstructions,commonFaults}',
      'stopRules',packet.packet_json#>'{assessmentSummary,proposedSafety,stopRules}',
      'recoveryEvidenceState','no_universal_recovery_interval_established',
      'recoveryDecisionInputs',jsonb_build_array(
        'total_and_per_leg_contacts','prior_sprinting_and_jumping',
        'surface_and_footwear','lower_leg_or_hamstring_symptoms',
        'coordination_or_speed_drift','next_session_demand'),
      'humanReviewRequired',TRUE),
    programming_profile_json=jsonb_build_object(
      'intent',packet.packet_json#>>'{assessmentSummary,proposedTaxonomy,intent}',
      'dosage',packet.packet_json#>'{assessmentSummary,proposedDosage}',
      'qualityGate',packet.packet_json#>>'{assessmentSummary,proposedDosage,progressWhen}',
      'overallDifficulty',(packet.packet_json#>>'{assessmentSummary,proposedDifficulty,baseOverallDifficulty}')::SMALLINT,
      'difficultyModel','max_exercise_complexity_physical_difficulty',
      'structurallySelectable',definition.slug=ANY(selectable_slugs),
      'programmingDecision',packet.packet_json#>>'{assessmentSummary,programmingDecision}',
      'humanReviewRequired',TRUE),
    status='review',updated_at=now()
  FROM coaching.exercise_definition_v1 definition,family_packet_seed packet
  WHERE variant.definition_id=definition.id
    AND definition.facility_id=1 AND definition.slug=packet.definition_slug
    AND definition.status<>'archived' AND variant.status<>'archived'
    AND variant.variant_key='baseline';

  UPDATE coaching.exercise_delivery_profile_v1 profile
  SET role=CASE WHEN NOT(definition.slug=ANY(selectable_slugs)) THEN 'avoid'
      WHEN definition.slug IN('ankle-pogo-in-place',
        'distance-jump-straight-leg-bound','straight-leg-bounds-to-sprint')
        AND profile.phase_key='output' THEN 'primary'
      WHEN definition.slug IN('ankling-drill',
        'distance-jump-straight-leg-bound-march')
        AND profile.phase_key='movement_intelligence' THEN 'primary'
      ELSE 'secondary' END,
    purpose=CASE WHEN definition.slug=ANY(selectable_slugs)
      THEN packet.packet_json#>>'{assessmentSummary,proposedTaxonomy,intent}'
      ELSE 'Quarantined pending exact identity, ordered contact sequence, setup, dose unit, and finish adjudication.' END,
    phase_suitability=CASE WHEN NOT(definition.slug=ANY(selectable_slugs)) THEN 1
      WHEN profile.phase_key IN('movement_intelligence','output') THEN 84 ELSE 68 END,
    methodology_alignment=CASE WHEN NOT(definition.slug=ANY(selectable_slugs))
      THEN 1 ELSE 82 END,
    objective_relevance_json=jsonb_build_object(
      'intent',packet.packet_json#>>'{assessmentSummary,proposedTaxonomy,intent}',
      'movementPatterns',packet.packet_json#>'{assessmentSummary,proposedTaxonomy,movementPatterns}',
      'identitySequenceResolved',definition.slug=ANY(selectable_slugs),
      'humanReviewRequired',TRUE),
    dosage_json=packet.packet_json#>'{assessmentSummary,proposedDosage}',
    quality_gate=coalesce(
      packet.packet_json#>>'{assessmentSummary,proposedDosage,progressWhen}',
      packet.packet_json#>>'{assessmentSummary,programmingDecision}'),
    stop_rules=ARRAY(SELECT jsonb_array_elements_text(
      packet.packet_json#>'{assessmentSummary,proposedSafety,stopRules}')),
    coach_instructions=array_to_string(ARRAY(SELECT jsonb_array_elements_text(
      packet.packet_json#>'{assessmentSummary,proposedInstructions,coachCues}')),'; '),
    athlete_instructions=array_to_string(ARRAY(SELECT jsonb_array_elements_text(
      packet.packet_json#>'{assessmentSummary,proposedInstructions,athleteInstructions}')),' '),
    expected_adaptation=packet.packet_json#>>'{assessmentSummary,proposedTaxonomy,intent}',
    equipment_required=ARRAY(SELECT jsonb_array_elements_text(
      packet.packet_json#>'{assessmentSummary,proposedConstraints,requiredEquipment}')),
    logistics_json=jsonb_build_object(
      'environment',packet.packet_json#>'{assessmentSummary,proposedConstraints,environment}',
      'contactAccounting',packet.packet_json#>>'{assessmentSummary,proposedLoadProfile,landingContactsPerRep}',
      'oneAthletePerStationOrLane',TRUE,'staggeredStarts',TRUE,
      'clearFinishBeforeNextStart',TRUE,
      'structurallySelectable',definition.slug=ANY(selectable_slugs)),
    time_model_json=CASE
      WHEN definition.slug='ankle-pogo-in-place' THEN
        '{"setupSeconds":45,"workSecondsPerSet":20,"transitionSeconds":15,"restSecondsPerSet":60,"estimateConfidence":"candidate"}'::JSONB
      WHEN definition.slug='ankling-drill' THEN
        '{"setupSeconds":60,"workSecondsPerPass":25,"transitionSeconds":15,"restSecondsPerPass":45,"estimateConfidence":"candidate"}'::JSONB
      WHEN definition.slug='distance-jump-straight-leg-bound-march' THEN
        '{"setupSeconds":60,"workSecondsPerPass":30,"transitionSeconds":15,"restSecondsPerPass":45,"estimateConfidence":"candidate"}'::JSONB
      WHEN definition.slug='distance-jump-straight-leg-bound' THEN
        '{"setupSeconds":75,"workSecondsPerAttempt":20,"transitionSeconds":20,"restSecondsPerAttempt":150,"estimateConfidence":"candidate"}'::JSONB
      WHEN definition.slug='straight-leg-bounds-to-sprint' THEN
        '{"setupSeconds":90,"workSecondsPerAttempt":30,"transitionSeconds":30,"restSecondsPerAttempt":210,"estimateConfidence":"candidate"}'::JSONB
      ELSE jsonb_build_object('prescribable',FALSE,
        'reason','identity_and_contact_sequence_unresolved') END,
    dose_scaling_json=jsonb_build_object(
      'dimensions',jsonb_build_array(
        'contacts_or_distance','cadence_or_velocity','amplitude','constraint','rest'),
      'progressOneDimensionAtATime',TRUE,'preserveQualityBeforeVolume',TRUE),
    measurement_json=jsonb_build_object(
      'primary','declared_contacts_distance_or_seconds',
      'secondary',jsonb_build_array(
        'contact_pattern_accuracy','contact_sound','posture','speed_or_rhythm','symptoms'),
      'failedContactsExcluded',TRUE),
    support_prompts_json=jsonb_build_object(
      'before','Confirm the exact pattern, surface, lane, finish, dose, and stop signal.',
      'during','Watch contact order, sound, posture, reach, symmetry, equipment clearance, and fatigue drift.',
      'after','Record contacts or distance, rest, failures, symptoms, and selected profile.'),
    status='review',updated_at=now()
  FROM coaching.exercise_variant_v1 variant
  JOIN coaching.exercise_definition_v1 definition ON definition.id=variant.definition_id
  JOIN family_packet_seed packet ON packet.definition_slug=definition.slug
  WHERE profile.variant_id=variant.id AND definition.facility_id=1
    AND definition.status<>'archived' AND variant.status<>'archived';

  CREATE TEMP TABLE context_profile_seed(
    definition_slug TEXT NOT NULL,profile_key TEXT NOT NULL,phase_key TEXT NOT NULL,
    purpose TEXT NOT NULL,suitability SMALLINT NOT NULL,dosage_json JSONB NOT NULL,
    quality_gate TEXT NOT NULL,coach_instructions TEXT NOT NULL,
    athlete_instructions TEXT NOT NULL,
    PRIMARY KEY(definition_slug,profile_key)
  ) ON COMMIT DROP;
  INSERT INTO context_profile_seed VALUES
    ('ankle-pogo-in-place','low-pogo-preparation','prepare_and_access',
      'Stationary bilateral ankle-pogo delivery with deliberately low amplitude and a conservative contact cap; Low Pogos is an alias, not another exercise.',
      74,'{"sets":"1-3","contactsPerSet":"8-15_or_5-10_seconds","restSeconds":"30-75","intensity":"low_amplitude_preparation"}',
      'Contacts remain quiet, vertical, symmetric, pain-free, and low amplitude without knee-dominant sinking.',
      'Count every landing, cap amplitude, and end while contacts remain quiet and symmetric.',
      'Bounce lightly in place, stay tall, and stop before contacts get loud or slow.'),
    ('ankling-drill','dribble-march-learning-cadence','movement_intelligence',
      'Traveling Ankling Drill delivered at a deliberate dribble-march learning cadence; contact identity remains unchanged.',
      78,'{"sets":"2-3_passes","distancePerPass":"8-15_metres","restSeconds":"walk_back_or_30-60","intensity":"deliberate_learning_cadence"}',
      'Short alternating contacts stay close beneath the hips with tall posture, quiet sound, and no flight.',
      'Use dribble imagery only to organize short alternating contacts; do not add a separate hop or reach.',
      'Move forward with tiny alternating steps, stay tall, and keep each contact close beneath you.'),
    ('ankling-drill','ankling-walk-learning-cadence','movement_intelligence',
      'Traveling Ankling Drill delivered at walking cadence to learn contact placement before cadence increases.',
      76,'{"sets":"2-3_passes","distancePerPass":"8-15_metres","restSeconds":"walk_back_or_30-60","intensity":"walking_learning_cadence"}',
      'The athlete preserves alternating no-flight contacts, short steps, tall posture, and relaxed rhythm before progressing cadence.',
      'Keep it a traveling ankling pattern at walking cadence; progress cadence only when contact placement is repeatable.',
      'Walk the ankling rhythm with short steps and quiet contacts close beneath your hips.');

  INSERT INTO coaching.exercise_delivery_profile_v1(
    variant_id,profile_key,phase_key,role,purpose,phase_suitability,
    methodology_alignment,objective_relevance_json,dosage_json,quality_gate,
    stop_rules,coach_instructions,athlete_instructions,expected_adaptation,
    equipment_required,logistics_json,substitution_ids,status,time_model_json,
    dose_scaling_json,measurement_json,support_prompts_json)
  SELECT variant.id,seed.profile_key,seed.phase_key,'conditional',seed.purpose,
    seed.suitability,80,
    jsonb_build_object('identityUnchanged',TRUE,'contextProfile',seed.profile_key,
      'humanReviewRequired',TRUE),seed.dosage_json,seed.quality_gate,
    ARRAY['pain','limp','balance_loss','contact_noise_or_cadence_deterioration',
      'posture_or_contact_pattern_changes'],seed.coach_instructions,
    seed.athlete_instructions,seed.purpose,definition.required_equipment,
    jsonb_build_object('oneAthletePerStationOrLane',TRUE,
      'clearFinishOrStation',TRUE),'{}'::UUID[],'review',
    jsonb_build_object('setupSeconds',45,'workSecondsPerSetOrPass',25,
      'transitionSeconds',15,'restSecondsPerSetOrPass',45,
      'estimateConfidence','candidate'),
    jsonb_build_object('dimensions',jsonb_build_array(
      'contacts_or_distance','cadence','amplitude','rest'),
      'progressOneDimensionAtATime',TRUE),
    jsonb_build_object('primary','clean_contacts_or_distance',
      'secondary',jsonb_build_array('posture','sound','rhythm','symptoms')),
    jsonb_build_object(
      'before','Confirm the identity-preserving context and dose.',
      'during','Stop when the base movement contract changes.',
      'after','Record clean contacts, distance, symptoms, and context profile.')
  FROM context_profile_seed seed
  JOIN coaching.exercise_definition_v1 definition
    ON definition.facility_id=1 AND definition.slug=seed.definition_slug
      AND definition.status<>'archived'
  JOIN coaching.exercise_variant_v1 variant
    ON variant.definition_id=definition.id AND variant.variant_key='baseline'
      AND variant.status<>'archived'
  ON CONFLICT(variant_id,profile_key)
  DO UPDATE SET phase_key=EXCLUDED.phase_key,role='conditional',
    purpose=EXCLUDED.purpose,phase_suitability=EXCLUDED.phase_suitability,
    methodology_alignment=EXCLUDED.methodology_alignment,
    objective_relevance_json=EXCLUDED.objective_relevance_json,
    dosage_json=EXCLUDED.dosage_json,quality_gate=EXCLUDED.quality_gate,
    stop_rules=EXCLUDED.stop_rules,coach_instructions=EXCLUDED.coach_instructions,
    athlete_instructions=EXCLUDED.athlete_instructions,
    expected_adaptation=EXCLUDED.expected_adaptation,
    equipment_required=EXCLUDED.equipment_required,
    logistics_json=EXCLUDED.logistics_json,
    substitution_ids='{}'::UUID[],status='review',
    time_model_json=EXCLUDED.time_model_json,
    dose_scaling_json=EXCLUDED.dose_scaling_json,
    measurement_json=EXCLUDED.measurement_json,
    support_prompts_json=EXCLUDED.support_prompts_json,updated_at=now()
  WHERE coaching.exercise_delivery_profile_v1.status='review';

  INSERT INTO coaching.exercise_section_evidence_v1(
    definition_id,reviewed_card_version,section_key,source_url,source_title,
    source_publisher,source_kind,claims_json,evidence_quality,review_status,
    reviewer_user_id,reviewed_at)
  SELECT definition.id,definition.card_version,evidence.item->>'sectionKey',
    evidence.item->>'sourceUrl',evidence.item->>'sourceTitle',
    evidence.item->>'sourcePublisher',evidence.item->>'sourceKind',
    evidence.item->'claims',(evidence.item->>'evidenceQuality')::SMALLINT,
    'candidate',NULL,NULL
  FROM family_packet_seed packet
  CROSS JOIN LATERAL jsonb_array_elements(packet.packet_json->'evidence') evidence(item)
  JOIN coaching.exercise_definition_v1 definition
    ON definition.facility_id=1 AND definition.slug=packet.definition_slug
      AND definition.status<>'archived'
  ON CONFLICT(definition_id,reviewed_card_version,section_key,source_url)
  DO UPDATE SET source_title=EXCLUDED.source_title,
    source_publisher=EXCLUDED.source_publisher,source_kind=EXCLUDED.source_kind,
    claims_json=EXCLUDED.claims_json,evidence_quality=EXCLUDED.evidence_quality,
    review_status='candidate',reviewer_user_id=NULL,reviewed_at=NULL,updated_at=now();

  INSERT INTO coaching.exercise_media_candidate_v1(
    definition_id,variant_id,reviewed_card_version,url,embed_url,video_id,title,
    channel_name,duration_seconds,language_code,captions_available,
    embedding_allowed,exact_variant_match,demonstration_quality_score,
    link_status,review_status,discovery_method,source_query,reviewer_user_id,
    reviewed_at,next_review_at,notes)
  SELECT definition.id,NULL,definition.card_version,media.item->>'url',
    'https://www.youtube-nocookie.com/embed/'
      ||substring(media.item->>'url' FROM 'v=([^&]+)'),
    substring(media.item->>'url' FROM 'v=([^&]+)'),media.item->>'title',
    media.item->>'channelName',NULL,'en',NULL,FALSE,NULL,NULL,
    'unverified','candidate','manual_research',media.item->>'sourceQuery',
    NULL,NULL,NULL,media.item->>'notes'
  FROM family_packet_seed packet
  CROSS JOIN LATERAL jsonb_array_elements(packet.packet_json->'mediaCandidates') media(item)
  JOIN coaching.exercise_definition_v1 definition
    ON definition.facility_id=1 AND definition.slug=packet.definition_slug
      AND definition.status<>'archived'
  ON CONFLICT(definition_id,reviewed_card_version,video_id)
  DO UPDATE SET variant_id=NULL,url=EXCLUDED.url,embed_url=EXCLUDED.embed_url,
    title=EXCLUDED.title,channel_name=EXCLUDED.channel_name,
    duration_seconds=NULL,language_code='en',captions_available=NULL,
    embedding_allowed=FALSE,exact_variant_match=NULL,
    demonstration_quality_score=NULL,link_status='unverified',
    review_status='candidate',discovery_method='manual_research',
    source_query=EXCLUDED.source_query,reviewer_user_id=NULL,reviewed_at=NULL,
    next_review_at=NULL,notes=EXCLUDED.notes,updated_at=now();

  INSERT INTO coaching.exercise_alternate_assessment_v1(
    definition_id,reviewed_card_version,alternate_name,classification,rationale,
    distinguishing_dimensions,proposed_card_json,review_status,reviewer_user_id,
    reviewed_at)
  SELECT definition.id,definition.card_version,alternate.item->>'name',
    alternate.item->>'classification',alternate.item->>'rationale',
    alternate.item->'distinguishingDimensions',NULL,'candidate',NULL,NULL
  FROM family_packet_seed packet
  CROSS JOIN LATERAL jsonb_array_elements(packet.packet_json->'alternateAssessments') alternate(item)
  JOIN coaching.exercise_definition_v1 definition
    ON definition.facility_id=1 AND definition.slug=packet.definition_slug
      AND definition.status<>'archived'
  ON CONFLICT(definition_id,reviewed_card_version,alternate_name)
  DO UPDATE SET classification=EXCLUDED.classification,
    rationale=EXCLUDED.rationale,
    distinguishing_dimensions=EXCLUDED.distinguishing_dimensions,
    proposed_card_json=NULL,review_status='candidate',reviewer_user_id=NULL,
    reviewed_at=NULL,updated_at=now();

