    similarity_score SMALLINT NOT NULL,dimensions TEXT[] NOT NULL,
    reason TEXT NOT NULL,conditions_json JSONB NOT NULL,
    PRIMARY KEY(from_slug,to_slug,relationship)
  ) ON COMMIT DROP;
